// n8n Code Node - Search Intent Processor (Single Consolidated Output)
// This processes DataForSEO Search Intent API responses into one comprehensive item

// Get the input data from the previous node
const inputData = $input.all();

// Initialize processing results
const allKeywords = [];
const intentSummary = {
    commercial: [],
    transactional: [],
    informational: [],
    navigational: []
};

// Try different ways to access the DataForSEO response
let dataforSeoResponse = null;

if (inputData && inputData.length > 0) {
    dataforSeoResponse = inputData[0].json;
}

if (!dataforSeoResponse && inputData && inputData.length > 0) {
    dataforSeoResponse = inputData[0];
}

// Process the DataForSEO response
if (dataforSeoResponse) {
    const responseArray = Array.isArray(dataforSeoResponse) ? dataforSeoResponse : [dataforSeoResponse];

    responseArray.forEach(response => {
        if (response && response.tasks && response.tasks.length > 0) {
            const task = response.tasks[0];

            if (task.result && task.result.length > 0) {
                const result = task.result[0];

                if (result.items && result.items.length > 0) {
                    result.items.forEach((item, index) => {
                        const keyword = item.keyword;
                        const primaryIntent = item.keyword_intent;
                        const secondaryIntents = item.secondary_keyword_intents || [];

                        // Calculate intent strength
                        const totalIntentStrength = primaryIntent.probability + 
                            (secondaryIntents.length > 0 ? secondaryIntents[0].probability : 0);

                        // Determine opportunity type
                        let opportunityType = 'standard';
                        let priority = 'medium';
                        let recommendedAction = 'Monitor';

                        if (primaryIntent.label === 'commercial' && primaryIntent.probability > 0.8) {
                            opportunityType = 'high_commercial';
                            priority = 'high';
                            recommendedAction = 'Create commercial landing page';
                        } else if (primaryIntent.label === 'transactional' || 
                                   secondaryIntents.some(intent => intent.label === 'transactional' && intent.probability > 0.3)) {
                            opportunityType = 'transactional_ready';
                            priority = 'high';
                            recommendedAction = 'Create conversion-focused page';
                        } else if (primaryIntent.label === 'informational' && 
                                   secondaryIntents.some(intent => intent.label === 'commercial')) {
                            opportunityType = 'content_opportunity';
                            priority = 'medium';
                            recommendedAction = 'Create educational content with commercial CTA';
                        } else if (secondaryIntents.length > 0 && secondaryIntents[0].probability > 0.4) {
                            opportunityType = 'mixed_intent';
                            priority = 'medium';
                            recommendedAction = 'Create versatile content addressing multiple intents';
                        }

                        // Create keyword data object
                        const keywordData = {
                            keyword: keyword,
                            primary_intent: primaryIntent.label,
                            primary_intent_probability: Math.round(primaryIntent.probability * 1000) / 1000,
                            secondary_intents: secondaryIntents.map(intent => ({
                                label: intent.label,
                                probability: Math.round(intent.probability * 1000) / 1000
                            })),
                            total_intent_strength: Math.round(totalIntentStrength * 1000) / 1000,
                            opportunity_type: opportunityType,
                            priority: priority,
                            recommended_action: recommendedAction,
                            seo_potential: primaryIntent.probability > 0.7 ? 'high' : 
                                         primaryIntent.probability > 0.5 ? 'medium' : 'low',
                            conversion_likelihood: primaryIntent.label === 'transactional' ? 'very_high' :
                                                 primaryIntent.label === 'commercial' ? 'high' :
                                                 primaryIntent.label === 'navigational' ? 'medium' : 'low',
                            content_type_suggestion: primaryIntent.label === 'informational' ? 'blog_post' :
                                                   primaryIntent.label === 'commercial' ? 'service_page' :
                                                   primaryIntent.label === 'transactional' ? 'landing_page' : 'category_page',
                            keyword_index: index + 1
                        };

                        allKeywords.push(keywordData);

                        // Add to intent summary
                        if (intentSummary[primaryIntent.label]) {
                            intentSummary[primaryIntent.label].push({
                                keyword: keyword,
                                probability: Math.round(primaryIntent.probability * 1000) / 1000
                            });
                        }
                    });
                }
            }
        }
    });
}

// Sort keywords by intent strength (highest first)
allKeywords.sort((a, b) => b.total_intent_strength - a.total_intent_strength);

// Group keywords by priority and opportunity type for easier processing
const highPriorityKeywords = allKeywords.filter(k => k.priority === 'high');
const mediumPriorityKeywords = allKeywords.filter(k => k.priority === 'medium');

// Create actionable keyword groups
const keywordGroups = {
    immediate_action: highPriorityKeywords.filter(k => 
        k.opportunity_type === 'high_commercial' || k.opportunity_type === 'transactional_ready'
    ),
    content_creation: allKeywords.filter(k => 
        k.opportunity_type === 'content_opportunity' || k.primary_intent === 'informational'
    ),
    mixed_strategy: allKeywords.filter(k => k.opportunity_type === 'mixed_intent'),
    monitoring: allKeywords.filter(k => k.opportunity_type === 'standard')
};

// Calculate keyword difficulty estimates based on intent patterns
const keywordDifficulty = allKeywords.map(k => ({
    keyword: k.keyword,
    estimated_difficulty: k.primary_intent === 'commercial' && k.primary_intent_probability > 0.8 ? 'high' :
                         k.primary_intent === 'transactional' ? 'medium' :
                         k.primary_intent === 'informational' ? 'low' : 'medium',
    competition_level: k.primary_intent_probability > 0.8 ? 'high' :
                      k.primary_intent_probability > 0.6 ? 'medium' : 'low'
}));

// Create consolidated output focused on actionable insights
const consolidatedOutput = {
    primary_targets: highPriorityKeywords.map(k => k.keyword),
    quick_wins: keywordGroups.immediate_action.map(k => ({
        keyword: k.keyword,
        action: k.recommended_action,
        priority: k.priority,
        conversion_potential: k.conversion_likelihood,
        content_type: k.content_type_suggestion
    })),
    content_opportunities: keywordGroups.content_creation.map(k => ({
        keyword: k.keyword,
        content_type: k.content_type_suggestion,
        intent: k.primary_intent,
        opportunity: k.recommended_action
    })),
    keyword_difficulty_analysis: keywordDifficulty,
    strategic_recommendations: {
        high_priority_actions: highPriorityKeywords.map(k => `${k.recommended_action} for "${k.keyword}"`),
        content_calendar_suggestions: keywordGroups.content_creation.map(k => ({
            keyword: k.keyword,
            content_format: k.content_type_suggestion,
            target_intent: k.primary_intent,
            cta_strategy: k.primary_intent === 'informational' ? 'soft_lead_gen' : 'direct_conversion'
        }))
    },
    all_keywords: allKeywords
};

// Return single consolidated item
return [{ json: consolidatedOutput }];

// Universal DataForSEO Keyword Ideas Content Processor
// Works for any industry, business type, and SEO campaign

function processKeywordIdeasForContent(dataForSEOResponse) {
    const response = Array.isArray(dataForSEOResponse) ? dataForSEOResponse[0] : dataForSEOResponse;

    // Handle different response structures
    if (!response.tasks || !response.tasks[0] || !response.tasks[0].result || !response.tasks[0].result[0]) {
        throw new Error("Invalid DataForSEO response structure");
    }

    const items = response.tasks[0].result[0].items;
    const seedKeyword = response.tasks[0].data.keywords[0]; // Original seed keyword

    // Filter and clean keywords
    const relevantItems = filterRelevantKeywords(items, seedKeyword);

    // Structure output for universal SEO content creation
    const contentStrategy = {
        campaign: {
            seedKeyword: seedKeyword,
            totalKeywords: relevantItems.length,
            totalSearchVolume: relevantItems.reduce((sum, item) => sum + item.keyword_info.search_volume, 0),
            avgCPC: (relevantItems.reduce((sum, item) => sum + item.keyword_info.cpc, 0) / relevantItems.length).toFixed(2),
            competitiveLevel: getOverallCompetitiveLevel(relevantItems),
            marketInsights: getMarketInsights(relevantItems)
        },

        opportunityMatrix: {
            quickWins: getQuickWins(relevantItems),
            highValue: getHighValueTargets(relevantItems), 
            longTerm: getLongTermTargets(relevantItems),
            local: getLocalOpportunities(relevantItems),
            brandProtection: getBrandOpportunities(relevantItems, seedKeyword)
        },

        contentStrategy: {
            pillarContent: generatePillarContent(relevantItems, seedKeyword),
            supportingContent: generateSupportingContent(relevantItems, seedKeyword),
            localContent: generateLocalContent(relevantItems),
            seasonalContent: generateSeasonalContent(relevantItems)
        },

        technicalSEO: {
            serpFeatures: analyzeSerpFeatures(relevantItems),
            schemaOpportunities: getSchemaOpportunities(relevantItems),
            competitorIntel: getCompetitorInsights(relevantItems),
            rankingFactors: getRankingFactors(relevantItems)
        },

        actionPlan: {
            immediate: getImmediateActions(relevantItems),
            shortTerm: getShortTermActions(relevantItems),
            longTerm: getLongTermActions(relevantItems),
            budget: getBudgetRecommendations(relevantItems),
            timeline: getTimelineRecommendations(relevantItems)
        }
    };

    return contentStrategy;
}

// UNIVERSAL FILTERING SYSTEM
function filterRelevantKeywords(items, seedKeyword) {
    const seedTerms = extractSeedTerms(seedKeyword);
    const minSearchVolume = 100; // Configurable threshold

    return items.filter(item => {
        const keyword = item.keyword.toLowerCase();

        // Basic quality filters
        if (item.keyword_info.search_volume < minSearchVolume) return false;
        if (keyword.length < 3) return false;

        // Check relevance to seed keyword
        const relevanceScore = calculateRelevanceScore(keyword, seedTerms);
        if (relevanceScore < 0.3) return false;

        // Filter out irrelevant patterns (language learning, unrelated brands, etc.)
        const irrelevantPatterns = [
            /spanish|french|german|chinese|japanese/i,
            /translate|translation|meaning/i,
            /song|music|artist|album|lyrics/i,
            /movie|film|tv|show/i,
            /game|gaming|video/i,
            /hotel|resort|vacation(?!.*equipment)/i
        ];

        const isIrrelevant = irrelevantPatterns.some(pattern => pattern.test(keyword));
        if (isIrrelevant) return false;

        return true;
    }).sort((a, b) => b.keyword_info.search_volume - a.keyword_info.search_volume);
}

function extractSeedTerms(seedKeyword) {
    return seedKeyword.toLowerCase()
        .split(' ')
        .filter(term => term.length > 2)
        .filter(term => !['the', 'and', 'for', 'with', 'near'].includes(term));
}

function calculateRelevanceScore(keyword, seedTerms) {
    const keywordTerms = keyword.split(' ');
    let matches = 0;

    seedTerms.forEach(seedTerm => {
        if (keywordTerms.some(term => 
            term.includes(seedTerm) || seedTerm.includes(term) ||
            getSemanticSimilarity(term, seedTerm) > 0.7
        )) {
            matches++;
        }
    });

    return matches / seedTerms.length;
}

function getSemanticSimilarity(term1, term2) {
    // Simple similarity check - can be enhanced with more sophisticated matching
    const synonymGroups = [
        ['repair', 'fix', 'service', 'maintenance'],
        ['install', 'installation', 'setup', 'mount'],
        ['cost', 'price', 'pricing', 'quote', 'estimate'],
        ['near', 'nearby', 'local', 'area'],
        ['equipment', 'parts', 'supplies', 'tools'],
        ['company', 'service', 'contractor', 'professional']
    ];

    return synonymGroups.some(group => 
        group.includes(term1) && group.includes(term2)
    ) ? 0.8 : 0;
}

// OPPORTUNITY IDENTIFICATION
function getQuickWins(items) {
    return items
        .filter(item => 
            item.keyword_info.search_volume >= 500 &&
            item.keyword_info.competition <= 0.4 &&
            (item.keyword_properties?.keyword_difficulty || 0) <= 25 &&
            item.keyword_info.cpc >= 1.0
        )
        .sort((a, b) => calculateOpportunityScore(b) - calculateOpportunityScore(a))
        .slice(0, 15)
        .map(item => ({
            keyword: item.keyword,
            searchVolume: item.keyword_info.search_volume,
            cpc: item.keyword_info.cpc,
            competition: item.keyword_info.competition_level,
            difficulty: item.keyword_properties?.keyword_difficulty || 0,
            opportunityScore: calculateOpportunityScore(item),
            intent: item.search_intent_info?.main_intent || 'unknown',
            contentType: determineContentType(item),
            estimatedRankingTime: getEstimatedRankingTime(item),
            requiredEffort: getRequiredEffort(item)
        }));
}

function getHighValueTargets(items) {
    return items
        .filter(item => item.keyword_info.cpc >= 3.0 && item.keyword_info.search_volume >= 1000)
        .sort((a, b) => (b.keyword_info.cpc * b.keyword_info.search_volume) - (a.keyword_info.cpc * a.keyword_info.search_volume))
        .slice(0, 12)
        .map(item => ({
            keyword: item.keyword,
            searchVolume: item.keyword_info.search_volume,
            cpc: item.keyword_info.cpc,
            monthlyValue: Math.round(item.keyword_info.search_volume * item.keyword_info.cpc),
            competition: item.keyword_info.competition_level,
            intent: item.search_intent_info?.main_intent || 'unknown',
            conversionPotential: assessConversionPotential(item),
            contentStrategy: generateContentStrategy(item),
            investmentLevel: getInvestmentLevel(item)
        }));
}

function getLongTermTargets(items) {
    return items
        .filter(item => 
            item.keyword_info.search_volume >= 2000 &&
            (item.keyword_properties?.keyword_difficulty || 0) >= 30
        )
        .sort((a, b) => b.keyword_info.search_volume - a.keyword_info.search_volume)
        .slice(0, 8)
        .map(item => ({
            keyword: item.keyword,
            searchVolume: item.keyword_info.search_volume,
            difficulty: item.keyword_properties?.keyword_difficulty || 0,
            cpc: item.keyword_info.cpc,
            timeToRank: getEstimatedRankingTime(item),
            authorityRequired: getAuthorityRequired(item),
            resourceNeeds: getResourceNeeds(item),
            strategicValue: assessStrategicValue(item)
        }));
}

function getLocalOpportunities(items) {
    const localTerms = ['near me', 'nearby', 'local', 'in my area'];
    const localKeywords = items.filter(item => 
        localTerms.some(term => item.keyword.toLowerCase().includes(term))
    );

    return {
        totalOpportunities: localKeywords.length,
        totalSearchVolume: localKeywords.reduce((sum, item) => sum + item.keyword_info.search_volume, 0),
        avgCPC: localKeywords.length > 0 ? 
            (localKeywords.reduce((sum, item) => sum + item.keyword_info.cpc, 0) / localKeywords.length).toFixed(2) : 0,
        keywords: localKeywords
            .sort((a, b) => b.keyword_info.search_volume - a.keyword_info.search_volume)
            .slice(0, 10)
            .map(item => ({
                keyword: item.keyword,
                searchVolume: item.keyword_info.search_volume,
                cpc: item.keyword_info.cpc,
                hasLocalPack: item.serp_info?.serp_item_types?.includes('local_pack') || false,
                competition: item.keyword_info.competition_level,
                localStrategy: generateLocalStrategy(item)
            })),
        optimization: {
            gmbRequired: true,
            localSchema: true,
            citationBuilding: true,
            reviewManagement: true,
            localContent: true
        }
    };
}

function getBrandOpportunities(items, seedKeyword) {
    // Extract potential brand terms from high-volume keywords
    const brandKeywords = items.filter(item => {
        const keyword = item.keyword.toLowerCase();
        return /[a-z]+'?s|brand|company|manufacturer/.test(keyword) ||
               keyword.split(' ').some(word => word[0] === word[0].toUpperCase());
    });

    return {
        totalOpportunities: brandKeywords.length,
        keywords: brandKeywords.slice(0, 8).map(item => ({
            keyword: item.keyword,
            searchVolume: item.keyword_info.search_volume,
            cpc: item.keyword_info.cpc,
            brandStrategy: generateBrandStrategy(item, seedKeyword)
        })),
        recommendations: [
            "Monitor brand mentions and variations",
            "Create comparison content for competitive brands",
            "Develop brand-specific expertise content",
            "Consider brand partnership opportunities"
        ]
    };
}

// CONTENT STRATEGY GENERATION
function generatePillarContent(items, seedKeyword) {
    const topCategories = categorizeKeywords(items);

    return Object.keys(topCategories)
        .filter(category => topCategories[category].length >= 3)
        .map(category => ({
            category: category,
            pillarTitle: generatePillarTitle(category, seedKeyword),
            targetKeywords: topCategories[category]
                .slice(0, 8)
                .map(item => item.keyword),
            estimatedTraffic: topCategories[category]
                .reduce((sum, item) => sum + item.keyword_info.search_volume, 0),
            contentStructure: generateContentStructure(category),
            internalLinking: generateInternalLinkingStrategy(topCategories[category]),
            contentDepth: "3000+ words",
            updateFrequency: getUpdateFrequency(category)
        }));
}

function generateSupportingContent(items, seedKeyword) {
    const contentTypes = {
        howTo: items.filter(item => 
            /how to|how do|guide|tutorial|step/.test(item.keyword.toLowerCase())
        ),
        comparison: items.filter(item => 
            /vs|versus|compare|comparison|best|top/.test(item.keyword.toLowerCase())
        ),
        cost: items.filter(item => 
            /cost|price|pricing|quote|estimate|expensive/.test(item.keyword.toLowerCase())
        ),
        problemSolving: items.filter(item => 
            /problem|issue|fix|repair|troubleshoot|not working/.test(item.keyword.toLowerCase())
        )
    };

    const supportingContent = {};

    Object.keys(contentTypes).forEach(type => {
        if (contentTypes[type].length > 0) {
            supportingContent[type] = {
                totalKeywords: contentTypes[type].length,
                estimatedTraffic: contentTypes[type].reduce((sum, item) => sum + item.keyword_info.search_volume, 0),
                contentIdeas: contentTypes[type]
                    .sort((a, b) => b.keyword_info.search_volume - a.keyword_info.search_volume)
                    .slice(0, 5)
                    .map(item => ({
                        title: generateContentTitle(item.keyword, type),
                        keyword: item.keyword,
                        searchVolume: item.keyword_info.search_volume,
                        cpc: item.keyword_info.cpc,
                        contentAngle: generateContentAngle(item, type),
                        cta: generateCTA(item, type)
                    }))
            };
        }
    });

    return supportingContent;
}

function generateLocalContent(items) {
    const localKeywords = items.filter(item => 
        /near me|nearby|local|in \w+|area/.test(item.keyword.toLowerCase())
    );

    if (localKeywords.length === 0) return null;

    return {
        locationPages: localKeywords.map(item => ({
            keyword: item.keyword,
            pageType: "Service Area Page",
            title: generateLocalTitle(item.keyword),
            contentSections: [
                "Service area coverage",
                "Local expertise and knowledge", 
                "Response times and availability",
                "Local customer testimonials",
                "Community involvement"
            ],
            localSEO: {
                gmbOptimization: true,
                localSchema: true,
                citationBuilding: true,
                localKeywords: true
            }
        })),
        serviceAreas: {
            primary: "Main service area targeting",
            secondary: "Extended coverage areas",
            radius: "Recommended 25-mile radius"
        }
    };
}

function generateSeasonalContent(items) {
    const seasonalAnalysis = analyzeSeasonality(items);

    return {
        seasonalTrends: seasonalAnalysis,
        contentCalendar: {
            Q1: generateQuarterlyContent(items, 1),
            Q2: generateQuarterlyContent(items, 2),
            Q3: generateQuarterlyContent(items, 3),
            Q4: generateQuarterlyContent(items, 4)
        },
        evergreen: items
            .filter(item => hasStableSearchVolume(item))
            .slice(0, 10)
            .map(item => ({
                keyword: item.keyword,
                searchVolume: item.keyword_info.search_volume,
                stability: "Year-round opportunity"
            }))
    };
}

// TECHNICAL SEO ANALYSIS
function analyzeSerpFeatures(items) {
    const features = {};
    let totalKeywords = 0;

    items.forEach(item => {
        totalKeywords++;
        if (item.serp_info?.serp_item_types) {
            item.serp_info.serp_item_types.forEach(feature => {
                features[feature] = (features[feature] || 0) + 1;
            });
        }
    });

    // Calculate percentages and opportunities
    const featureOpportunities = {};
    Object.keys(features).forEach(feature => {
        featureOpportunities[feature] = {
            count: features[feature],
            percentage: ((features[feature] / totalKeywords) * 100).toFixed(1),
            opportunity: getSerpFeatureOpportunity(feature, features[feature])
        };
    });

    return featureOpportunities;
}

function getSchemaOpportunities(items) {
    const schemaTypes = {
        LocalBusiness: items.filter(item => 
            /near me|local|area/.test(item.keyword.toLowerCase())
        ).length,
        Service: items.filter(item => 
            item.search_intent_info?.main_intent === 'transactional'
        ).length,
        FAQPage: items.filter(item => 
            item.serp_info?.serp_item_types?.includes('people_also_ask')
        ).length,
        HowTo: items.filter(item => 
            /how to|guide|tutorial/.test(item.keyword.toLowerCase())
        ).length,
        Product: items.filter(item => 
            /equipment|product|tool|part/.test(item.keyword.toLowerCase())
        ).length
    };

    return Object.keys(schemaTypes)
        .filter(type => schemaTypes[type] > 0)
        .map(type => ({
            schemaType: type,
            opportunities: schemaTypes[type],
            priority: getSchemaPriority(type, schemaTypes[type]),
            implementation: getSchemaImplementation(type)
        }));
}

// HELPER FUNCTIONS
function calculateOpportunityScore(item) {
    const volume = item.keyword_info.search_volume;
    const cpc = item.keyword_info.cpc;
    const competition = item.keyword_info.competition || 0.5;
    const difficulty = item.keyword_properties?.keyword_difficulty || 30;

    // Weighted scoring formula
    return Math.round(
        (volume * 0.3) + 
        (cpc * 100 * 0.3) + 
        ((1 - competition) * 100 * 0.2) + 
        ((100 - difficulty) * 0.2)
    );
}

function determineContentType(item) {
    const keyword = item.keyword.toLowerCase();
    const intent = item.search_intent_info?.main_intent;

    if (/near me|local|area/.test(keyword)) return "Location Page";
    if (/cost|price|pricing/.test(keyword)) return "Pricing Guide";
    if (/how to|guide|tutorial/.test(keyword)) return "How-To Guide";
    if (/vs|versus|compare/.test(keyword)) return "Comparison Page";
    if (/repair|fix|problem/.test(keyword)) return "Problem-Solving Guide";
    if (intent === 'transactional') return "Service Page";
    if (intent === 'commercial') return "Commercial Page";
    return "Information Page";
}

function getEstimatedRankingTime(item) {
    const difficulty = item.keyword_properties?.keyword_difficulty || 30;
    const competition = item.keyword_info.competition || 0.5;

    if (difficulty <= 20 && competition <= 0.3) return "2-4 months";
    if (difficulty <= 40 && competition <= 0.6) return "4-8 months";
    return "8-12+ months";
}

function categorizeKeywords(items) {
    const categories = {};

    items.forEach(item => {
        const keyword = item.keyword.toLowerCase();
        let category = 'general';

        if (/repair|fix|service|maintenance/.test(keyword)) category = 'repair_service';
        else if (/install|installation|setup/.test(keyword)) category = 'installation';
        else if (/cost|price|pricing|quote/.test(keyword)) category = 'pricing';
        else if (/equipment|parts|supplies|tools/.test(keyword)) category = 'equipment';
        else if (/how to|guide|tutorial/.test(keyword)) category = 'educational';
        else if (/near me|local|area/.test(keyword)) category = 'local';

        if (!categories[category]) categories[category] = [];
        categories[category].push(item);
    });

    return categories;
}

function generateContentTitle(keyword, type) {
    const templates = {
        howTo: `${capitalizeFirst(keyword)}: Complete Step-by-Step Guide`,
        comparison: `${capitalizeFirst(keyword)}: 2025 Comparison & Buyer's Guide`,
        cost: `${capitalizeFirst(keyword)}: Complete Cost Guide & Pricing Factors`,
        problemSolving: `${capitalizeFirst(keyword)}: Expert Solutions & Fixes`
    };

    return templates[type] || `${capitalizeFirst(keyword)}: Complete Guide`;
}

function capitalizeFirst(str) {
    return str.charAt(0).toUpperCase() + str.slice(1);
}

function getOverallCompetitiveLevel(items) {
    const avgCompetition = items.reduce((sum, item) => sum + (item.keyword_info.competition || 0.5), 0) / items.length;
    const avgDifficulty = items.reduce((sum, item) => sum + (item.keyword_properties?.keyword_difficulty || 30), 0) / items.length;

    if (avgCompetition <= 0.3 && avgDifficulty <= 25) return "Low Competition Market";
    if (avgCompetition <= 0.6 && avgDifficulty <= 50) return "Medium Competition Market";
    return "High Competition Market";
}

function getMarketInsights(items) {
    const insights = [];

    const highVolumeCount = items.filter(item => item.keyword_info.search_volume >= 10000).length;
    const lowCompCount = items.filter(item => (item.keyword_info.competition || 0.5) <= 0.3).length;
    const highCPCCount = items.filter(item => item.keyword_info.cpc >= 5.0).length;

    if (highVolumeCount > items.length * 0.2) {
        insights.push("High search volume market with significant traffic potential");
    }

    if (lowCompCount > items.length * 0.3) {
        insights.push("Multiple low-competition opportunities available");
    }

    if (highCPCCount > items.length * 0.1) {
        insights.push("High commercial value keywords present - premium market");
    }

    return insights;
}

// More helper functions for completeness...
function getImmediateActions(items) {
    const actions = [];

    const quickWins = items.filter(item => 
        (item.keyword_info.competition || 0.5) <= 0.3 && 
