// STRATEGIC Bing SERP Analysis - Focus on Opportunities & Differences from Google
// Delivers clear, actionable insights for Bing optimization

/**
 * Analyzes the Bing SERP API response to extract strategic insights.
 * @param {object | object[]} apiResponse - The raw JSON response from the SERP API.
 * @returns {object} A structured analysis object with strategic recommendations.
 */
function analyzeSerpBing(apiResponse) {
  // 1. Robust Data Extraction
  if (!apiResponse) {
    throw new Error("API response is null or undefined.");
  }
  const root = Array.isArray(apiResponse) ? apiResponse[0] : apiResponse;

  if (!root || !root.tasks || !root.tasks[0] || !root.tasks[0].result || !root.tasks[0].result[0]) {
    return { 
      overview: { keyword: "Invalid Input", searchEngine: "Bing", analysisDate: new Date().toISOString() }, 
      localPack: { competitionLevel: "Unknown", topCompetitors: [] }, 
      opportunities: [], 
      quickWins: [], 
      strategy: { reasoning: ["Invalid input data provided to analysis function."] }, 
      insights: { mainOpportunity: "Invalid Input" } 
    };
  }

  const task = root.tasks[0];
  const result = task.result[0];
  const items = result.items || [];
  const keyword = task.data?.keyword || result.keyword || "Not provided";
  const datetime = result.datetime || new Date().toISOString();

  // Initialize the main analysis object
  const analysis = {
    searchOverview: { keyword, searchEngine: "Bing", searchDate: datetime },
    localPackAnalysis: {},
    topOpportunities: [],
    quickWins: [],
    strategy: {}
  };

  // 2. Analyze SERP Features
  const aiOverview = items.find(item => item.type && item.type.trim().toLowerCase() === 'ai_overview');
  const hasAiOverview = !!(aiOverview && aiOverview.items && aiOverview.items.length > 0);

  const videoContent = items.find(item => item.type && item.type.trim().toLowerCase() === 'video');
  const hasVideoResults = !!(videoContent && videoContent.items && videoContent.items.length > 0);

  // *** FIXED: Correctly identify and handle the local pack data structure. ***
  // This now handles both nested and flat local_pack items.
  const localPackItems = items.filter(item => item.type && item.type.trim().toLowerCase() === 'local_pack');
  const organicResults = items.filter(item => item.type && item.type.trim().toLowerCase() === 'organic');

  // 3. Analyze Local Pack
  if (localPackItems.length > 0) {
    // The new input provides local pack items as a flat list. This now handles that correctly.
    analysis.localPackAnalysis = analyzeLocalCompetition(localPackItems);
  } else {
    analysis.localPackAnalysis = { status: "No local pack found", competitionLevel: "Not Applicable", topBusinesses: [] };
  }

  // 4. Analyze Organic Results & Quick Wins
  organicResults.forEach(item => {
    const weaknesses = analyzeCompetitorWeaknesses(item);
    if (weaknesses.length >= 2) {
      analysis.quickWins.push({
        position: item.rank_absolute,
        domain: item.domain,
        opportunity: `Outrank at position ${item.rank_absolute}`,
        weaknesses: weaknesses.slice(0, 2),
        difficulty: "Medium"
      });
    }
  });

  // 5. Identify Top Strategic Opportunities
  if (hasAiOverview) {
    analysis.topOpportunities.push({ type: "AI Overview Presence", impact: "Very High", effort: "High", description: "Bing's AI answer is at the top. Becoming a source is a primary goal.", action: "Create comprehensive, well-structured content that directly answers the user's query.", priority: 1 });
  }
  if (hasVideoResults) {
    analysis.topOpportunities.push({ type: "Video SERP Presence", impact: "High", effort: "Medium", description: "Video results are present, showing video is a key content type.", action: "Create and promote a competitive video to rank in the existing video block.", priority: 2 });
  }
  if (localPackItems.length === 0) {
    analysis.topOpportunities.push({ type: "Local Pack Absence", impact: "High", effort: "Medium", description: "No local pack is ranking, a major opportunity for local intent keywords.", action: "Create and fully optimize a Bing Places for Business listing.", priority: 3 });
  } else if (analysis.localPackAnalysis.competitionLevel === "Weak") {
    analysis.topOpportunities.push({ type: "Local Pack Domination", impact: "High", effort: "Low", description: "Weak local competition with low ratings/reviews.", action: "Optimize Bing Places + acquire 30+ reviews.", priority: 3 });
  }
  if (analysis.quickWins.length >= 3) {
    analysis.topOpportunities.push({ type: "Organic Competitor Weakness", impact: "Medium", effort: "Medium", description: `${analysis.quickWins.length} top organic competitors have significant weaknesses.`, action: "Create a high-quality page addressing competitor weaknesses.", priority: 4 });
  }

  // 6. Generate Final Strategy
  const topOpps = analysis.topOpportunities.sort((a, b) => a.priority - b.priority);
  analysis.strategy = {
    topPriority: topOpps[0] || null,
    secondPriority: topOpps[1] || null,
    thirdPriority: topOpps[2] || null,
    reasoning: generateStrategyReasoning(analysis, hasVideoResults, hasAiOverview, localPackItems.length === 0)
  };

  // 7. Format Final Output
  return {
    overview: {
      keyword: analysis.searchOverview.keyword,
      searchEngine: "Bing",
      analysisDate: analysis.searchOverview.searchDate
    },
    localPack: {
      competitionLevel: analysis.localPackAnalysis.competitionLevel,
      averageRating: analysis.localPackAnalysis.averageRating || null,
      averageReviews: analysis.localPackAnalysis.averageReviews || null,
      topCompetitors: analysis.localPackAnalysis.topBusinesses || []
    },
    opportunities: topOpps,
    quickWins: analysis.quickWins.slice(0, 3),
    strategy: analysis.strategy,
    insights: {
      mainOpportunity: analysis.strategy.topPriority?.type || "No major opportunity",
      competitionLevel: analysis.localPackAnalysis.competitionLevel,
      quickWinCount: analysis.quickWins.length,
      recommendedFocus: analysis.strategy.topPriority?.action || "Monitor competition"
    }
  };
}

// --- HELPER FUNCTIONS ---

function analyzeLocalCompetition(localItems) {
  let totalRating = 0, totalReviews = 0, ratedBusinesses = 0;
  const topBusinesses = [];

  localItems.slice(0, 3).forEach((business, index) => {
    topBusinesses.push({
      rank: index + 1, name: business.title, domain: business.domain,
      rating: business.rating?.value || null, reviewCount: business.rating?.votes_count || 0,
      hasWebsite: !!business.domain, weaknesses: identifyKeyWeaknesses(business)
    });
    if (business.rating?.value) {
      totalRating += business.rating.value;
      totalReviews += business.rating.votes_count;
      ratedBusinesses++;
    }
  });

  const competitionLevel = assessLocalCompetitionLevel(topBusinesses);
  return {
    status: "Local pack found",
    competitionLevel: competitionLevel,
    averageRating: ratedBusinesses > 0 ? (totalRating / ratedBusinesses).toFixed(1) : 0,
    averageReviews: ratedBusinesses > 0 ? Math.round(totalReviews / ratedBusinesses) : 0,
    topBusinesses
  };
}

function identifyKeyWeaknesses(business) {
  const weaknesses = [];
  if (!business.rating || business.rating.value < 3.8) weaknesses.push("Poor rating");
  if (!business.rating || business.rating.votes_count < 25) weaknesses.push("Few reviews");
  if (!business.domain) weaknesses.push("No website");
  return weaknesses;
}

function assessLocalCompetitionLevel(businesses) {
  if (businesses.length === 0) return "Not Applicable";
  const avgRating = businesses.reduce((sum, b) => sum + (b.rating || 0), 0) / businesses.length;
  const avgReviews = businesses.reduce((sum, b) => sum + (b.reviewCount || 0), 0) / businesses.length;
  if (avgRating < 4.0 || avgReviews < 40) return "Weak";
  if (avgRating < 4.4 || avgReviews < 80) return "Medium";
  return "Strong";
}

function analyzeCompetitorWeaknesses(result) {
  const weaknesses = [];
  if (!result.rating) weaknesses.push("No ratings");
  if (!result.description || result.description.length < 120) weaknesses.push("Short description");
  if (isDirectoryListing(result.domain)) weaknesses.push("Directory listing");
  return weaknesses;
}

function isDirectoryListing(domain) {
  const directories = ['yelp.com', 'thumbtack.com', 'angi.com', 'homeadvisor.com', 'yellowpages.com', 'birdeye.com', 'nextdoor.com'];
  return directories.some(dir => domain?.includes(dir));
}

function generateStrategyReasoning(analysis, hasVideo, hasAi, noLocalPack) {
  const reasoning = [];
  if (hasAi) reasoning.push("Bing's AI Overview is dominant; becoming a source is the top priority.");
  if (hasVideo) reasoning.push("Bing is featuring video; creating video is a direct path to visibility.");
  if (noLocalPack) reasoning.push("The absence of a local pack is a significant opportunity.");
  else if (analysis.localPackAnalysis.competitionLevel === "Weak") reasoning.push("Local competition is weak and can be outranked.");
  if (analysis.quickWins.length >= 3) reasoning.push(`${analysis.quickWins.length} weak organic competitors create multiple ranking opportunities.`);
  if (reasoning.length === 0) reasoning.push("The SERP is competitive; focus on high-quality content and technical SEO.");
  return reasoning;
}

