// UNIVERSAL SERP Google Analysis - Works for ANY Company & Industry
// Dynamic analysis based on input data structure

function analyzeSerpGoogle(apiResponse, clientData = null) {
  // Handle different input formats
  let data;
  if (Array.isArray(apiResponse)) {
    data = apiResponse[0];
  } else {
    data = apiResponse;
  }

  const result = data.tasks[0].result[0];
  const items = result.items;

  // Extract client info dynamically (if available)
  const clientInfo = extractClientInfo(clientData);

  // Initialize universal analysis structure
  const analysis = {
    // Core search performance
    searchOverview: {
      keyword: result.keyword,
      totalResults: result.se_results_count,
      competitionLevel: categorizeCompetition(result.se_results_count),
      searchDate: result.datetime
    },

    // Client's current status (dynamic)
    clientStatus: {
      companyName: clientInfo.companyName,
      targetDomain: clientInfo.domain,
      isVisible: false,
      bestPosition: null,
      pages: [],
      immediateActions: []
    },

    // Local competition analysis
    localCompetition: {
      topThreats: [],
      averageRating: 0,
      reviewBenchmark: 0,
      opportunities: [],
      marketGaps: []
    },

    // AI Overview intelligence
    aiOverview: {
      isActive: false,
      contentSummary: [],
      sourcesUsed: [],
      clientCited: false,
      opportunities: []
    },

    // Content strategy opportunities
    contentStrategy: {
      priorityQuestions: [],
      contentGaps: [],
      industryTopics: [],
      quickWins: []
    },

    // Competitive advantages
    competitiveAdvantages: {
      weakCompetitors: [],
      rankingOpportunities: [],
      differentiationPoints: []
    },

    // Actionable roadmap
    actionPlan: {
      immediate: [],
      week1: [],
      week2: [],
      month1: []
    }
  };

  // 1. ANALYZE CLIENT'S CURRENT SERP PERFORMANCE
  const organicResults = items.filter(item => item.type === 'organic');
  let clientPages = [];

  if (clientInfo.domain) {
    clientPages = organicResults.filter(result => 
      result.domain === clientInfo.domain || 
      result.url?.includes(clientInfo.domain)
    );
  }

  if (clientPages.length > 0) {
    analysis.clientStatus.isVisible = true;
    analysis.clientStatus.bestPosition = Math.min(...clientPages.map(p => p.rank_absolute));

    clientPages.forEach(page => {
      analysis.clientStatus.pages.push({
        position: page.rank_absolute,
        title: page.title,
        url: page.url,
        description: page.description,
        pageType: categorizePageType(page.url, result.keyword)
      });
    });

    // Generate position-based actions
    analysis.clientStatus.immediateActions = generatePositionActions(
      analysis.clientStatus.bestPosition,
      clientInfo.companyName
    );
  } else {
    analysis.clientStatus.immediateActions = [
      "Target domain not visible in search results",
      "Check technical SEO and indexing status", 
      "Verify target pages are optimized for keywords",
      "Consider comprehensive SEO audit"
    ];
  }

  // 2. ANALYZE LOCAL PACK COMPETITION
  const localPack = items.filter(item => item.type === 'local_pack');
  if (localPack.length > 0) {
    let totalRating = 0;
    let totalReviews = 0;

    localPack.forEach((business, index) => {
      const competitor = {
        rank: index + 1,
        name: business.title,
        rating: business.rating?.value || 0,
        reviewCount: business.rating?.votes_count || 0,
        phone: business.phone,
        website: business.domain,
        description: business.description,
        threatLevel: index === 0 ? "High" : index === 1 ? "Medium" : "Low",
        weaknesses: identifyCompetitorWeaknesses(business),
        isClient: business.domain === clientInfo.domain
      };

      analysis.localCompetition.topThreats.push(competitor);

      if (business.rating?.value) totalRating += business.rating.value;
      if (business.rating?.votes_count) totalReviews += business.rating.votes_count;
    });

    analysis.localCompetition.averageRating = (totalRating / localPack.length).toFixed(1);
    analysis.localCompetition.reviewBenchmark = Math.round(totalReviews / localPack.length);

    // Generate competitive opportunities
    analysis.localCompetition.opportunities = generateCompetitiveOpportunities(
      analysis.localCompetition.averageRating,
      analysis.localCompetition.reviewBenchmark,
      clientInfo.companyName
    );
  }

  // 3. ANALYZE AI OVERVIEW CONTENT
  const peopleAlsoAsk = items.find(item => item.type === 'people_also_ask');
  if (peopleAlsoAsk && peopleAlsoAsk.items) {
    peopleAlsoAsk.items.forEach(question => {
      if (question.expanded_element) {
        question.expanded_element.forEach(element => {
          if (element.type === 'people_also_ask_ai_overview_expanded_element' && element.items) {
            analysis.aiOverview.isActive = true;

            element.items.forEach(aiItem => {
              if (aiItem.text && aiItem.text.length > 50) {
                analysis.aiOverview.contentSummary.push({
                  question: question.title,
                  content: aiItem.text.substring(0, 200) + "...",
                  title: aiItem.title || "Overview",
                  sourceCount: aiItem.references?.length || 0
                });

                // Track sources and check for client
                if (aiItem.references) {
                  aiItem.references.forEach(ref => {
                    if (ref.domain && !analysis.aiOverview.sourcesUsed.find(s => s.domain === ref.domain)) {
                      const isClient = ref.domain === clientInfo.domain;
                      if (isClient) analysis.aiOverview.clientCited = true;

                      analysis.aiOverview.sourcesUsed.push({
                        domain: ref.domain,
                        title: ref.title,
                        isCompetitor: isIndustryDomain(ref.domain, result.keyword),
                        isClient: isClient
                      });
                    }
                  });
                }
              }
            });
          }
        });
      }
    });

    // Generate AI Overview opportunities
    analysis.aiOverview.opportunities = generateAIOverviewOpportunities(
      analysis.aiOverview.isActive,
      analysis.aiOverview.clientCited,
      analysis.aiOverview.sourcesUsed.length,
      clientInfo.companyName
    );
  }

  // 4. EXTRACT CONTENT OPPORTUNITIES
  if (peopleAlsoAsk && peopleAlsoAsk.items) {
    peopleAlsoAsk.items.forEach((question, index) => {
      const priority = determinePriority(question.title);
      if (priority === "High" || index < 7) {
        analysis.contentStrategy.priorityQuestions.push({
          question: question.title,
          priority,
          contentType: suggestContentType(question.title),
          targetKeyword: extractMainKeyword(question.title),
          hasAIOverview: analysis.aiOverview.contentSummary.some(ai => ai.question === question.title),
          commercialIntent: assessCommercialIntent(question.title)
        });
      }
    });
  }

  // Identify industry-specific content gaps
  const industryThemes = generateIndustryThemes(result.keyword);
  industryThemes.forEach(theme => {
    const hasContent = organicResults.slice(0, 10).some(result => 
      result.title.toLowerCase().includes(theme.topic.toLowerCase()) ||
      result.description?.toLowerCase().includes(theme.topic.toLowerCase())
    );

    if (!hasContent) {
      analysis.contentStrategy.contentGaps.push({
        topic: theme.topic,
        priority: theme.priority,
        reason: theme.reason,
        contentType: theme.contentType,
        targetKeywords: theme.keywords
      });
    }
  });

  // 5. IDENTIFY COMPETITIVE ADVANTAGES
  organicResults.slice(0, 15).forEach(result => {
    if (result.domain !== clientInfo.domain) {
      const weaknesses = analyzeCompetitorWeaknesses(result);

      if (weaknesses.length >= 2) {
        analysis.competitiveAdvantages.weakCompetitors.push({
          position: result.rank_absolute,
          domain: result.domain,
          title: result.title,
          weaknesses,
          opportunity: `Outrank at position ${result.rank_absolute}`,
          difficulty: assessRankingDifficulty(result.rank_absolute, weaknesses.length)
        });
      }
    }
  });

  // 6. CREATE UNIVERSAL ACTION PLAN
  analysis.actionPlan = generateActionPlan(analysis, clientInfo);

  return analysis;
}

// HELPER FUNCTIONS - All Made Generic

function extractClientInfo(clientData) {
  if (!clientData) {
    return {
      companyName: null,
      domain: null,
      industry: null
    };
  }

  // Handle different input formats
  const data = Array.isArray(clientData) ? clientData[0] : clientData;

  return {
    companyName: data["Company Name"] || data.companyName || data.name || null,
    domain: extractDomainFromUrl(data.website || data.url || data.domain),
    industry: data.industry || inferIndustryFromKeyword(data["What is the main topic or keyword?"] || "")
  };
}

function extractDomainFromUrl(url) {
  if (!url) return null;
  try {
    const domain = url.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
    return domain;
  } catch {
    return null;
  }
}

function categorizeCompetition(totalResults) {
  if (totalResults > 1000000) return "Very High";
  if (totalResults > 500000) return "High";
  if (totalResults > 100000) return "Medium";
  return "Low";
}

function categorizePageType(url, keyword) {
  if (!url) return "Unknown";

  const urlLower = url.toLowerCase();
  const keywordParts = keyword.toLowerCase().split(' ');

  if (keywordParts.some(part => urlLower.includes(part))) return "Target Page";
  if (urlLower.includes('blog') || urlLower.includes('article')) return "Blog Page";
  if (urlLower.includes('service') || urlLower.includes('product')) return "Service Page";
  if (url.split('/').length <= 4) return "Main Page";
  return "General Page";
}

function identifyCompetitorWeaknesses(business) {
  const weaknesses = [];

  if (!business.rating || business.rating.value < 4.0) weaknesses.push("Low/no rating");
  if (!business.rating || business.rating.votes_count < 50) weaknesses.push("Few reviews");
  if (!business.domain) weaknesses.push("No website");
  if (!business.phone) weaknesses.push("No phone visible");
  if (!business.description?.includes("years")) weaknesses.push("No experience mentioned");

  return weaknesses;
}

function generatePositionActions(position, companyName) {
  const company = companyName || "Target company";

  if (!position) {
    return [
      "Target domain not found in search results",
      "Check page indexing and technical SEO issues",
      "Verify keyword targeting and on-page optimization"
    ];
  }

  if (position > 20) {
    return [
      `Currently ranking at position ${position} - requires major improvement`,
      "Complete SEO overhaul needed",
      "Focus on technical SEO, content quality, and authority building"
    ];
  }

  if (position > 10) {
    return [
      `Ranking at position ${position} - significant optimization needed`,
      "Improve on-page SEO and content quality",
      "Build domain authority and local citations"
    ];
  }

  if (position > 5) {
    return [
      `Good visibility at position ${position} - opportunity to reach top 5`,
      "Fine-tune content optimization and user experience",
      "Focus on conversion optimization"
    ];
  }

  return [
    `Strong visibility at position ${position}`,
    "Maintain current rankings and expand keyword targeting",
    "Focus on conversion optimization and market expansion"
  ];
}

function generateCompetitiveOpportunities(avgRating, reviewBenchmark, companyName) {
  return [
    `Target rating above ${avgRating} to be competitive`,
    `Approximately ${reviewBenchmark + 50} reviews needed for market leadership`,
    "Focus on review acquisition and reputation management",
    "Optimize Google Business Profile for local visibility"
  ];
}

function generateAIOverviewOpportunities(isActive, clientCited, sourcesCount, companyName) {
  const opportunities = [];

  if (isActive) {
    if (!clientCited) {
      opportunities.push({
        type: "CRITICAL",
        opportunity: "Target domain not cited in AI Overview",
        action: "Create comprehensive, authoritative content for AI Overview inclusion",
        priority: "High"
      });
    }

    if (sourcesCount < 5) {
      opportunities.push({
        type: "HIGH",
        opportunity: "Limited sources in AI Overview - opportunity to dominate",
        action: "Develop detailed, well-structured content targeting AI Overview",
        priority: "High"
      });
    }
  } else {
    opportunities.push({
      type: "OPPORTUNITY",
      opportunity: "No AI Overview active - chance to trigger one",
      action: "Create comprehensive content to potentially trigger AI Overview",
      priority: "Medium"
    });
  }

  return opportunities;
}

function generateIndustryThemes(keyword) {
  const keywordLower = keyword.toLowerCase();
  const themes = [];

  // Universal themes that apply to most service businesses
  themes.push(
    { topic: "Cost Guide", priority: "High", reason: "High search volume", contentType: "Pricing Guide", keywords: [`${keyword} cost`, `${keyword} price`] },
    { topic: "Emergency Service", priority: "High", reason: "High commercial intent", contentType: "Service Page", keywords: [`emergency ${keyword}`, `urgent ${keyword}`] },
    { topic: "DIY vs Professional", priority: "Medium", reason: "Common user concern", contentType: "Comparison", keywords: [`diy ${keyword}`, `${keyword} professional`] }
  );

  // Industry-specific themes based on keyword
  if (keywordLower.includes('repair')) {
    themes.push(
      { topic: "Troubleshooting Guide", priority: "High", reason: "Pre-service content", contentType: "How-to Guide", keywords: [`${keyword.replace('repair', 'troubleshooting')}`, `${keyword} problems`] },
      { topic: "Replacement vs Repair", priority: "Medium", reason: "Decision-making content", contentType: "Comparison", keywords: [`${keyword.replace('repair', 'replacement')}`, `repair vs replace`] }
    );
  }

  if (keywordLower.includes('service')) {
    themes.push(
      { topic: "Service Areas", priority: "Medium", reason: "Local SEO", contentType: "Location Pages", keywords: [`${keyword} near me`, `local ${keyword}`] },
      { topic: "Maintenance Tips", priority: "Medium", reason: "Educational content", contentType: "Guide", keywords: [`${keyword.replace('service', 'maintenance')}`, `${keyword} tips`] }
    );
  }

  return themes;
}

function isIndustryDomain(domain, keyword) {
  const keywordParts = keyword.toLowerCase().split(' ');
  const domainLower = domain.toLowerCase();

  return keywordParts.some(part => 
    domainLower.includes(part) || 
    part.length > 4 && domainLower.includes(part)
  );
}

function analyzeCompetitorWeaknesses(result) {
  const weaknesses = [];

  if (!result.rating) weaknesses.push("No reviews/ratings");
  if (result.rating && result.rating.value < 4.0) weaknesses.push("Low rating");
  if (!result.description?.match(/\(\d{3}\)/)) weaknesses.push("No phone number visible");
  if (!result.description?.includes("years")) weaknesses.push("No experience mentioned");
  if (result.title.length > 60) weaknesses.push("Title too long");
  if (!result.description || result.description.length < 120) weaknesses.push("Poor meta description");

  return weaknesses;
}

function assessRankingDifficulty(position, weaknessCount) {
  if (position <= 5 && weaknessCount >= 3) return "Medium";
  if (position <= 10 && weaknessCount >= 2) return "Medium";
  if (position > 10) return "Easy";
  return "Hard";
}

function generateActionPlan(analysis, clientInfo) {
  const plan = {
    immediate: [],
    week1: [],
    week2: [],
    month1: []
  };

  // Immediate actions
  if (!analysis.clientStatus.isVisible || analysis.clientStatus.bestPosition > 20) {
    plan.immediate.push("URGENT: Technical SEO audit and indexing check");
  }

  if (analysis.aiOverview.isActive && !analysis.aiOverview.clientCited) {
    plan.immediate.push("PRIORITY: Create AI Overview-optimized content");
  }

  // Week 1 actions
  plan.week1.push("Optimize primary landing page for target keyword");
  plan.week1.push("Set up review acquisition campaign");
  plan.week1.push("Create FAQ content for top People Also Ask questions");

  // Week 2 actions
  plan.week2.push("Build local citations and directory listings");
  plan.week2.push("Create high-priority content gap pages");
  plan.week2.push("Optimize contact information and local SEO signals");

  // Month 1 actions
  plan.month1.push("Develop comprehensive content strategy");
  plan.month1.push("Launch link building campaign");
  plan.month1.push("Monitor and optimize conversion funnel");

  return plan;
}

function determinePriority(question) {
  const q = question.toLowerCase();
  if (q.includes('cost') || q.includes('price') || q.includes('how much')) return 'High';
  if (q.includes('repair') || q.includes('fix') || q.includes('service')) return 'High';
  if (q.includes('replace') || q.includes('diy') || q.includes('how to')) return 'Medium';
  return 'Low';
}

function suggestContentType(question) {
  const q = question.toLowerCase();
  if (q.includes('cost') || q.includes('price')) return 'Pricing Guide';
  if (q.includes('how to') || q.includes('repair')) return 'How-to Guide';
  if (q.includes('best') || q.includes('vs')) return 'Comparison';
  if (q.includes('signs') || q.includes('when')) return 'Diagnostic Guide';
  return 'Informational Article';
}

function assessCommercialIntent(question) {
  const q = question.toLowerCase();
  if (q.includes('cost') || q.includes('price') || q.includes('service')) return 'High';
  if (q.includes('repair') || q.includes('replace') || q.includes('hire')) return 'Medium';
  return 'Low';
}

function extractMainKeyword(question) {
  const q = question.toLowerCase().replace(/[^\w\s]/g, '');
  const stopWords = ['what', 'when', 'where', 'how', 'why', 'does', 'much', 'your', 'the', 'is', 'are', 'can', 'should'];
  const words = q.split(' ').filter(word => 
    word.length > 3 && !stopWords.includes(word)
  );
  return words.slice(0, 3).join(' ');
}

function inferIndustryFromKeyword(keyword) {
  const k = keyword.toLowerCase();
  if (k.includes('repair') || k.includes('fix')) return 'repair services';
  if (k.includes('clean') || k.includes('maintenance')) return 'maintenance services';
  if (k.includes('install') || k.includes('setup')) return 'installation services';
  if (k.includes('pool') || k.includes('spa')) return 'pool services';
  if (k.includes('electric') || k.includes('electrical')) return 'electrical services';
  if (k.includes('plumb') || k.includes('water')) return 'plumbing services';
  return 'general services';
}

