            contentClusters: {},
            competitorAnalysis: {},
            seasonalInsights: {},
            recommendations: {},
            metadata: {
                totalKeywordsAnalyzed: items.length,
                processingNotes: [],
                apiResponse: {
                    seedKeyword: response.tasks[0].result[0].seed_keyword || 'Unknown',
                    itemsCount: response.tasks[0].result[0].items_count || 0,
                    totalCount: response.tasks[0].result[0].total_count || 0
                }
            }
        };

        // Handle cases with no keywords at all
        if (items.length === 0) {
            seoOpportunities.metadata.processingNotes.push("No keywords found in the API response");
            seoOpportunities.metadata.processingNotes.push("This may be due to: 1) Very specific/niche keyword, 2) Location-specific term with low search volume, 3) New or uncommon terminology");

            // Return basic structure with recommendations for no data
            seoOpportunities.recommendations = {
                primaryContent: {
                    mainTopic: `${response.tasks[0].result[0].seed_keyword || 'Your Service'} - Comprehensive Guide`,
                    targetKeywords: [],
                    contentType: "Service Landing Page",
                    estimatedTraffic: 0,
                    recommendedWordCount: "2000-3000 words",
                    note: "No keyword data available - consider broader keyword research"
                },
                supportingContent: [],
                localSEO: {
                    priority: "HIGH",
                    targetKeywords: [],
                    gmb_optimization: true,
                    localStrategy: ["Focus on Google My Business optimization", "Build local citations", "Target broader service terms"]
                },
                technicalSEO: {
                    featuredSnippets: [],
                    peopleAlsoAsk: [],
                    schemaMarkup: ["LocalBusiness", "Service", "Organization"],
                    contentGaps: []
                },
                competitiveStrategy: {
                    targetDifficulty: "Start with low competition long-tail keywords",
                    contentDepth: "Create comprehensive content to establish topical authority",
                    linkBuildingTargets: [],
                    recommendation: "Consider researching broader related terms like 'electrical services', 'circuit breaker repair', or location-specific electrical terms"
                }
            };

            return seoOpportunities;
        }

        if (items.length < 10) {
            seoOpportunities.metadata.processingNotes.push(`Only ${items.length} keywords available for analysis`);
        }

        // Extract location early for use in filtering
        const primaryLocation = extractLocationFromKeywords(items) || 'local area';

        // 1. PRIMARY KEYWORD ANALYSIS
        const primaryKeyword = items[0];
        if (primaryKeyword && primaryKeyword.keyword_data) {
            seoOpportunities.primaryKeywordData = {
                keyword: primaryKeyword.keyword_data.keyword,
                searchVolume: primaryKeyword.keyword_data.keyword_info?.search_volume || 0,
                cpc: primaryKeyword.keyword_data.keyword_info?.cpc || 0,
                competition: primaryKeyword.keyword_data.keyword_info?.competition_level || 'unknown',
                searchIntent: primaryKeyword.keyword_data.search_intent_info?.main_intent || 'unknown',
                difficulty: primaryKeyword.keyword_data.keyword_properties?.keyword_difficulty || 0,
                serpFeatures: primaryKeyword.keyword_data.serp_info?.serp_item_types || [],
                seasonality: {
                    peak: getSeasonalPeak(primaryKeyword.keyword_data.keyword_info?.monthly_searches),
                    trend: primaryKeyword.keyword_data.keyword_info?.search_volume_trend || 'unknown'
                }
            };
        } else {
            seoOpportunities.metadata.processingNotes.push("Primary keyword data is incomplete");
        }

        // 2. HIGH-VALUE KEYWORD IDENTIFICATION - Smart filtering for rankable keywords
        const minSearchVolume = items.length < 10 ? 10 : 50; // Minimum traffic to be worthwhile
        const maxCompetition = 0.7; // Max 70% competition for better ranking chances
        const maxDifficulty = 40; // Focus on keywords with difficulty under 40
        const minCPC = 0.5; // Some commercial intent

        // Smart filtering based on multiple ranking factors
        const filteredHighValueKeywords = items
            .filter(item => {
                const kw = item.keyword_data?.keyword_info;
                const props = item.keyword_data?.keyword_properties;
                if (!kw) return false;

                // Multi-factor filtering for rankability
                const hasReasonableVolume = kw.search_volume >= minSearchVolume && kw.search_volume <= 10000; // Not too competitive
                const hasLowCompetition = kw.competition <= maxCompetition;
                const hasCommercialIntent = kw.cpc >= minCPC;
                const hasReasonableDifficulty = !props?.keyword_difficulty || props.keyword_difficulty <= maxDifficulty;

                // Check for long-tail opportunities (4+ words often easier to rank)
                const wordCount = item.keyword_data.keyword.split(' ').length;
                const isLongTail = wordCount >= 4;

                // Prioritize local and question keywords (easier to rank)
                const isLocal = item.keyword_data.keyword.toLowerCase().includes('near me') || 
                               item.keyword_data.keyword.toLowerCase().includes('in ') ||
                               item.keyword_data.keyword.toLowerCase().includes(primaryLocation?.toLowerCase() || '');
                const isQuestion = ['how', 'what', 'where', 'when', 'why', 'can', 'does', 'is'].some(q => 
                    item.keyword_data.keyword.toLowerCase().startsWith(q));

                // Apply more lenient criteria for long-tail, local, or question keywords
                if (isLongTail || isLocal || isQuestion) {
                    return hasReasonableVolume && (hasLowCompetition || hasReasonableDifficulty);
                }

                // Standard criteria for other keywords
                return hasReasonableVolume && hasLowCompetition && hasCommercialIntent && hasReasonableDifficulty;
            })
            .map(item => ({
                keyword: item.keyword_data.keyword,
                searchVolume: item.keyword_data.keyword_info.search_volume,
                cpc: item.keyword_data.keyword_info.cpc,
                competition: item.keyword_data.keyword_info.competition_level,
                difficulty: item.keyword_data.keyword_properties?.keyword_difficulty || 0,
                intent: item.keyword_data.search_intent_info?.main_intent || 'unknown',
                opportunity: calculateOpportunityScore(item.keyword_data),
                rankingFactors: {
                    wordCount: item.keyword_data.keyword.split(' ').length,
                    isLongTail: item.keyword_data.keyword.split(' ').length >= 4,
                    isLocal: item.keyword_data.keyword.toLowerCase().includes('near me') || item.keyword_data.keyword.toLowerCase().includes('in '),
                    isQuestion: ['how', 'what', 'where', 'when', 'why', 'can', 'does', 'is'].some(q => 
                        item.keyword_data.keyword.toLowerCase().startsWith(q)),
                    hasLowBacklinks: (item.keyword_data.avg_backlinks_info?.backlinks || 0) < 50
                },
                relatedTerms: item.related_keywords || []
            }))
            .sort((a, b) => b.opportunity - a.opportunity);

        // If no keywords match high-value criteria, include all available keywords
        if (filteredHighValueKeywords.length === 0 && items.length > 0) {
            seoOpportunities.metadata.processingNotes.push("No keywords met high-value criteria, including all available keywords");
            seoOpportunities.highValueKeywords = items
                .filter(item => item.keyword_data?.keyword_info)
                .map(item => ({
                    keyword: item.keyword_data.keyword,
                    searchVolume: item.keyword_data.keyword_info?.search_volume || 0,
                    cpc: item.keyword_data.keyword_info?.cpc || 0,
                    competition: item.keyword_data.keyword_info?.competition_level || 'unknown',
                    difficulty: item.keyword_data.keyword_properties?.keyword_difficulty || 0,
                    intent: item.keyword_data.search_intent_info?.main_intent || 'unknown',
                    opportunity: calculateOpportunityScore(item.keyword_data),
                    relatedTerms: item.related_keywords || []
                }))
                .sort((a, b) => b.opportunity - a.opportunity);
        } else {
            seoOpportunities.highValueKeywords = filteredHighValueKeywords.slice(0, Math.min(10, filteredHighValueKeywords.length));
        }

        // 3. LOCAL/PROXIMITY KEYWORDS
        seoOpportunities.localKeywords = items
            .filter(item => item.keyword_data?.keyword?.includes('near me'))
            .map(item => ({
                keyword: item.keyword_data.keyword,
                searchVolume: item.keyword_data.keyword_info?.search_volume || 0,
                cpc: item.keyword_data.keyword_info?.cpc || 0,
                competition: item.keyword_data.keyword_info?.competition_level || 'unknown',
                serpFeatures: item.keyword_data.serp_info?.serp_item_types || [],
                localPackPresent: item.keyword_data.serp_info?.serp_item_types?.includes('local_pack') || false
            }));

        if (seoOpportunities.localKeywords.length === 0) {
            seoOpportunities.metadata.processingNotes.push("No local/proximity keywords found");
        }

        // 4. BRAND-SPECIFIC OPPORTUNITIES
        const brands = extractBrandsFromKeywords(items);
        brands.forEach(brand => {
            const brandKeywords = items.filter(item => 
                item.keyword_data?.keyword?.toLowerCase().includes(brand.toLowerCase())
            );

            if (brandKeywords.length > 0) {
                const validBrandKeywords = brandKeywords.filter(kw => kw.keyword_data?.keyword_info?.search_volume);
                seoOpportunities.brandSpecificKeywords[brand] = {
                    totalKeywords: brandKeywords.length,
                    avgSearchVolume: validBrandKeywords.length > 0 
                        ? Math.round(validBrandKeywords.reduce((sum, kw) => 
                            sum + (kw.keyword_data.keyword_info?.search_volume || 0), 0) / validBrandKeywords.length)
                        : 0,
                    topKeywords: validBrandKeywords
                        .sort((a, b) => (b.keyword_data.keyword_info?.search_volume || 0) - (a.keyword_data.keyword_info?.search_volume || 0))
                        .slice(0, Math.min(5, validBrandKeywords.length))
                        .map(kw => ({
                            keyword: kw.keyword_data.keyword,
                            searchVolume: kw.keyword_data.keyword_info?.search_volume || 0,
                            cpc: kw.keyword_data.keyword_info?.cpc || 0
                        }))
                };
            }
        });

        if (Object.keys(seoOpportunities.brandSpecificKeywords).length === 0) {
            seoOpportunities.metadata.processingNotes.push("No brand-specific keywords identified");
        }

        // 5. CONTENT CLUSTER ANALYSIS (Dynamic Clustering)
        const clusters = identifyContentClusters(items);

        Object.keys(clusters).forEach(cluster => {
            if (clusters[cluster].length > 0) {
                const validKeywords = clusters[cluster].filter(kw => kw.keyword_data?.keyword_info);
                if (validKeywords.length > 0) {
                    seoOpportunities.contentClusters[cluster] = {
                        keywordCount: validKeywords.length,
                        totalSearchVolume: validKeywords.reduce((sum, kw) => 
                            sum + (kw.keyword_data.keyword_info?.search_volume || 0), 0),
                        avgCPC: validKeywords.length > 0 
                            ? (validKeywords.reduce((sum, kw) => 
                                sum + (kw.keyword_data.keyword_info?.cpc || 0), 0) / validKeywords.length).toFixed(2)
                            : "0.00",
                        topKeywords: validKeywords
                            .sort((a, b) => (b.keyword_data.keyword_info?.search_volume || 0) - (a.keyword_data.keyword_info?.search_volume || 0))
                            .slice(0, Math.min(3, validKeywords.length))
                            .map(kw => kw.keyword_data.keyword),
                        searchIntent: getMostCommonIntent(validKeywords)
                    };
                }
            }
        });

        if (Object.keys(seoOpportunities.contentClusters).length === 0) {
            seoOpportunities.metadata.processingNotes.push("No content clusters identified");
        }

        // 6. SEASONAL INSIGHTS
        if (items[0]?.keyword_data?.keyword_info?.monthly_searches) {
            seoOpportunities.seasonalInsights = {
                peakSeason: "May-July (Pool season opening)",
                demandPattern: "4x higher searches in summer months",
                planningRecommendation: "Create content 2-3 months before peak season",
                monthlyTrends: analyzeMonthlTrends(items[0].keyword_data.keyword_info.monthly_searches)
            };
        } else {
            seoOpportunities.seasonalInsights = {
                peakSeason: "Data not available",
                demandPattern: "Seasonal patterns unavailable",
                planningRecommendation: "Monitor search trends over time",
                monthlyTrends: { summer_peak: 0, winter_low: 0, spring_buildup: 0 }
            };
            seoOpportunities.metadata.processingNotes.push("Seasonal data not available");
        }

        // 7. COMPETITIVE ANALYSIS
        const itemsWithBacklinks = items.filter(item => item.keyword_data?.avg_backlinks_info?.backlinks);
        seoOpportunities.competitorAnalysis = {
            avgBacklinks: itemsWithBacklinks.length > 0 
                ? Math.round(itemsWithBacklinks.reduce((sum, item) => {
                    return sum + (item.keyword_data.avg_backlinks_info?.backlinks || 0);
                }, 0) / itemsWithBacklinks.length)
                : 0,
            competitionLevel: getMostCommonCompetition(items),
            opportunityGaps: identifyGaps(items),
            recommendedTargets: getRecommendedTargets(items)
        };

        // 8. ACTIONABLE RECOMMENDATIONS
        const seedKeyword = response.tasks[0].result[0].seed_keyword || 'your service';

        seoOpportunities.recommendations = {
            primaryContent: {
                mainTopic: generateMainTopic(seedKeyword, primaryLocation),
                targetKeywords: seoOpportunities.highValueKeywords.slice(0, Math.min(5, seoOpportunities.highValueKeywords.length)).map(kw => kw.keyword),
                contentType: determineContentType(seoOpportunities.primaryKeywordData.searchIntent),
                estimatedTraffic: seoOpportunities.highValueKeywords.slice(0, Math.min(5, seoOpportunities.highValueKeywords.length)).reduce((sum, kw) => sum + kw.searchVolume, 0),
                recommendedWordCount: getRecommendedWordCount(seoOpportunities.primaryKeywordData.searchIntent)
            },
            supportingContent: generateUniversalContentIdeas(seoOpportunities.contentClusters, seedKeyword),
            localSEO: {
                priority: seoOpportunities.localKeywords.length > 0 ? "HIGH" : "MEDIUM",
                targetKeywords: seoOpportunities.localKeywords.map(kw => kw.keyword),
                gmb_optimization: seoOpportunities.localKeywords.some(kw => kw.localPackPresent),
                localStrategy: generateLocalStrategy(seoOpportunities.localKeywords)
            },
            technicalSEO: {
                featuredSnippets: identifySnippetOpportunities(items),
                peopleAlsoAsk: extractPAAQuestions(items),
                schemaMarkup: generateSchemaRecommendations(seoOpportunities.primaryKeywordData.searchIntent, seoOpportunities.localKeywords.length > 0),
                contentGaps: identifyContentGaps(items)
            },
            competitiveStrategy: {
                targetDifficulty: getRecommendedDifficultyRange(items),
                contentDepth: getRecommendedContentDepth(seoOpportunities.competitorAnalysis),
                linkBuildingTargets: getLinkBuildingTargets(items)
            }
        };

        return seoOpportunities;

    } catch (error) {
        console.error("Error in processRelatedKeywords:", error);
        throw error;
    }
}

// HELPER FUNCTIONS

function extractBrandsFromKeywords(items) {
    try {
        const brands = new Set();
        const commonBrandTerms = [];

        items.forEach(item => {
            const keyword = item.keyword_data?.keyword?.toLowerCase();
            if (!keyword) return;

            const words = keyword.split(' ');

            // Look for capitalized brand names in original keywords
            words.forEach(word => {
                if (word.length > 3 && 
                    !['repair', 'service', 'near', 'cost', 'price', 'parts', 'kit', 'pump', 'pool'].includes(word)) {
                    commonBrandTerms.push(word);
                }
            });
        });

        // Count frequency and extract likely brands
        const brandCounts = {};
        commonBrandTerms.forEach(term => {
            brandCounts[term] = (brandCounts[term] || 0) + 1;
        });

        // Return brands that appear in multiple keywords (or at least once if few keywords)
        const minAppearances = items.length < 10 ? 1 : 2;
        return Object.keys(brandCounts).filter(brand => brandCounts[brand] >= minAppearances);
    } catch (error) {
        console.error("Error in extractBrandsFromKeywords:", error);
        return [];
    }
}

function identifyContentClusters(items) {
    try {
        const clusters = {};

        // Dynamic cluster identification based on common terms
        const clusterTerms = {
            'cost_pricing': ['cost', 'price', 'pricing', 'expensive', 'cheap', 'budget', 'affordable'],
            'repair_fix': ['repair', 'fix', 'broken', 'not_working', 'issue', 'problem'],
            'replacement': ['replace', 'replacement', 'new', 'install', 'installation'],
            'maintenance': ['maintenance', 'service', 'tune', 'check', 'clean'],
            'parts_components': ['parts', 'kit', 'component', 'seal', 'motor', 'gasket'],
            'emergency_urgent': ['emergency', 'urgent', 'immediate', '24/7', 'fast'],
            'diy_guide': ['how_to', 'guide', 'manual', 'instructions', 'steps'],
            'local_proximity': ['near_me', 'local', 'nearby', 'close']
        };

        Object.keys(clusterTerms).forEach(clusterName => {
            clusters[clusterName] = items.filter(item => {
                const keyword = item.keyword_data?.keyword?.toLowerCase().replace(/[^a-z0-9\s]/g, ' ');
                if (!keyword) return false;
                return clusterTerms[clusterName].some(term => 
                    keyword.includes(term.replace('_', ' '))
                );
            });
        });

        // Remove empty clusters
        Object.keys(clusters).forEach(key => {
            if (clusters[key].length === 0) {
                delete clusters[key];
            }
        });

        return clusters;
    } catch (error) {
        console.error("Error in identifyContentClusters:", error);
        return {};
    }
}

function getMostCommonIntent(clusterItems) {
    try {
        const intents = clusterItems
            .map(item => item.keyword_data?.search_intent_info?.main_intent)
            .filter(intent => intent);

        if (intents.length === 0) return 'unknown';

        const intentCounts = {};
        intents.forEach(intent => {
            intentCounts[intent] = (intentCounts[intent] || 0) + 1;
        });
        return Object.keys(intentCounts).reduce((a, b) => intentCounts[a] > intentCounts[b] ? a : b);
    } catch (error) {
        console.error("Error in getMostCommonIntent:", error);
        return 'unknown';
    }
}

function extractLocationFromKeywords(items) {
    try {
        const locationTerms = [];
        items.forEach(item => {
            const keyword = item.keyword_data?.keyword?.toLowerCase();
            if (!keyword) return;

            // Look for location indicators
            if (keyword.includes('near ') || keyword.includes(' in ') || keyword.includes(' florida') || keyword.includes(' ca') || keyword.includes(' texas')) {
                const parts = keyword.split(/near|in/);
                if (parts.length > 1) {
                    locationTerms.push(parts[1].trim());
                }
            }
        });

        return locationTerms.length > 0 ? locationTerms[0] : null;
    } catch (error) {
        console.error("Error in extractLocationFromKeywords:", error);
        return null;
    }
}

function generateMainTopic(seedKeyword, location) {
    try {
        const topicTemplates = {
            'repair': `${seedKeyword} in ${location}`,
            'service': `Professional ${seedKeyword} Services`,
            'installation': `${seedKeyword} Installation Guide`,
            'cost': `${seedKeyword} Cost Guide`,
            'maintenance': `${seedKeyword} Maintenance Tips`
        };

        // Determine topic type based on seed keyword
        for (const [type, template] of Object.entries(topicTemplates)) {
            if (seedKeyword.toLowerCase().includes(type)) {
                return template.replace(/\b\w/g, l => l.toUpperCase());
            }
        }

        return `Complete ${seedKeyword} Guide`.replace(/\b\w/g, l => l.toUpperCase());
    } catch (error) {
        console.error("Error in generateMainTopic:", error);
        return `${seedKeyword} Guide`;
    }
}

function determineContentType(searchIntent) {
    const contentTypes = {
        'transactional': 'Service Landing Page',
        'commercial': 'Product/Service Comparison Page', 
        'informational': 'Comprehensive Guide/Blog Post',
        'navigational': 'Brand/Location Specific Page',
        'unknown': 'Informational Content Page'
    };

    return contentTypes[searchIntent] || 'Informational Content Page';
}

function getRecommendedWordCount(searchIntent) {
    const wordCounts = {
        'transactional': '1500-2500 words',
        'commercial': '2000-3000 words',
        'informational': '2500-4000 words',
        'navigational': '1000-2000 words',
        'unknown': '2000-3000 words'
    };

    return wordCounts[searchIntent] || '2000-3000 words';
}

function generateUniversalContentIdeas(clusters, seedKeyword) {
    try {
        const ideas = [];

        Object.keys(clusters).forEach(cluster => {
            if (clusters[cluster] && clusters[cluster].keywordCount > 0) {
                const contentTitles = {
                    'cost_pricing': `Complete ${seedKeyword} Cost Guide & Pricing Breakdown`,
                    'repair_fix': `Ultimate ${seedKeyword} Troubleshooting & Repair Guide`,
                    'replacement': `When to Repair vs Replace: ${seedKeyword} Decision Guide`,
                    'maintenance': `Essential ${seedKeyword} Maintenance & Care Tips`,
                    'parts_components': `${seedKeyword} Parts Guide & Component Overview`,
                    'emergency_urgent': `Emergency ${seedKeyword} Services - What You Need to Know`,
                    'diy_guide': `DIY ${seedKeyword}: Step-by-Step Instructions`,
                    'local_proximity': `Local ${seedKeyword} Services: Finding the Right Provider`
                };

                if (contentTitles[cluster]) {
                    ideas.push({
                        contentTitle: contentTitles[cluster],
                        targetKeywords: clusters[cluster].topKeywords || [],
                        estimatedTraffic: clusters[cluster].totalSearchVolume || 0,
                        contentType: "Blog Post / Resource Page",
                        searchIntent: clusters[cluster].searchIntent || 'unknown',
                        priority: calculateContentPriority(clusters[cluster])
                    });
                }
            }
        });

        return ideas.sort((a, b) => b.priority - a.priority);
    } catch (error) {
        console.error("Error in generateUniversalContentIdeas:", error);
        return [];
    }
}

function generateLocalStrategy(localKeywords) {
    try {
        if (localKeywords.length === 0) return ["Focus on branded and general keywords"];

        const strategies = [];

        if (localKeywords.some(kw => kw.localPackPresent)) {
            strategies.push("Optimize Google My Business for local pack domination");
        }

        strategies.push("Create location-specific landing pages");
        strategies.push("Build local citations and directory listings");
        strategies.push("Generate location-based content and reviews");

        return strategies;
    } catch (error) {
        console.error("Error in generateLocalStrategy:", error);
        return ["Focus on local SEO optimization"];
    }
}

function generateSchemaRecommendations(searchIntent, hasLocalKeywords) {
    const schemas = ["Organization", "WebPage"];

    if (hasLocalKeywords) {
        schemas.push("LocalBusiness");
    }

    if (searchIntent === 'transactional') {
        schemas.push("Service", "Offer");
    }

    schemas.push("FAQPage", "BreadcrumbList");

    return schemas;
}

function identifyContentGaps(items) {
    try {
        const gaps = items
            .filter(item => {
                if (!item.keyword_data?.keyword_info) return false;

                // Focus on truly achievable gaps
                const hasVeryLowCompetition = item.keyword_data.keyword_info.competition < 0.3;
                const hasDecentVolume = item.keyword_data.keyword_info.search_volume >= 20 && 
                                       item.keyword_data.keyword_info.search_volume <= 500; // Sweet spot
                const hasLowDifficulty = (item.keyword_data.keyword_properties?.keyword_difficulty || 0) < 25;
                const hasLowBacklinks = (item.keyword_data.avg_backlinks_info?.backlinks || 0) < 20;

                // Check if it's a long-tail keyword (easier to rank)
                const isLongTail = item.keyword_data.keyword.split(' ').length >= 4;

                return (hasVeryLowCompetition && hasDecentVolume && hasLowDifficulty) || 
                       (isLongTail && hasLowBacklinks && hasDecentVolume);
            })
            .map(item => ({
                keyword: item.keyword_data.keyword,
                opportunity: 'Low competition gap - High ranking potential',
                volume: item.keyword_data.keyword_info.search_volume,
                competition: item.keyword_data.keyword_info.competition,
                difficulty: item.keyword_data.keyword_properties?.keyword_difficulty || 0,
                requiredBacklinks: item.keyword_data.avg_backlinks_info?.backlinks || 0,
                rankingPotential: 'High'
            }))
            .sort((a, b) => {
                // Prioritize by combination of low difficulty and decent volume
                const scoreA = (a.volume / 10) * (1 - (a.difficulty / 100));
                const scoreB = (b.volume / 10) * (1 - (b.difficulty / 100));
                return scoreB - scoreA;
            });

        // Return all gaps if less than 10, otherwise top 10
        return gaps.slice(0, Math.min(10, gaps.length));
    } catch (error) {
        console.error("Error in identifyContentGaps:", error);
        return [];
    }
}

function getRecommendedDifficultyRange(items) {
    try {
        const difficulties = items
            .map(item => item.keyword_data?.keyword_properties?.keyword_difficulty || 0)
            .filter(diff => diff > 0);

        if (difficulties.length === 0) return "Focus on 0-30 difficulty range";

        const avgDifficulty = difficulties.reduce((sum, diff) => sum + diff, 0) / difficulties.length;

        if (avgDifficulty < 20) return "Focus on 0-30 difficulty range";
        if (avgDifficulty < 40) return "Target 15-45 difficulty range";
        return "Consider 25-55 difficulty range with strong content";
    } catch (error) {
        console.error("Error in getRecommendedDifficultyRange:", error);
        return "Focus on 0-30 difficulty range";
    }
}

function getRecommendedContentDepth(competitorAnalysis) {
    if (competitorAnalysis.avgBacklinks < 10) return "In-depth content (2500+ words) can outrank competitors";
    if (competitorAnalysis.avgBacklinks < 50) return "Comprehensive content (3000+ words) with multimedia";
    return "Authority-level content (4000+ words) with expert insights required";
}

function getLinkBuildingTargets(items) {
    try {
        const targets = items
            .filter(item => {
                const backlinks = item.keyword_data?.avg_backlinks_info?.backlinks || 0;
                return backlinks > 0 && backlinks < 100; // Achievable targets
            })
            .sort((a, b) => (a.keyword_data.avg_backlinks_info?.backlinks || 0) - (b.keyword_data.avg_backlinks_info?.backlinks || 0))
            .map(item => ({
                keyword: item.keyword_data.keyword,
                avgBacklinks: item.keyword_data.avg_backlinks_info?.backlinks || 0,
                volume: item.keyword_data.keyword_info?.search_volume || 0
            }));

        // Return all targets if less than 5, otherwise top 5
        return targets.slice(0, Math.min(5, targets.length));
    } catch (error) {
        console.error("Error in getLinkBuildingTargets:", error);
        return [];
    }
}

function calculateContentPriority(cluster) {
    try {
        const avgCPC = parseFloat(cluster.avgCPC) || 0;
        const totalVolume = cluster.totalSearchVolume || 0;
        return Math.round((totalVolume * avgCPC) / 100);
    } catch (error) {
        console.error("Error in calculateContentPriority:", error);
        return 0;
    }
}

function calculateOpportunityScore(keywordData) {
    try {
        if (!keywordData?.keyword_info) return 0;

        const volume = keywordData.keyword_info.search_volume || 0;
        const competition = keywordData.keyword_info.competition || 1;
        const cpc = keywordData.keyword_info.cpc || 0;
        const difficulty = keywordData.keyword_properties?.keyword_difficulty || 50;
        const backlinks = keywordData.avg_backlinks_info?.backlinks || 100;

        // Enhanced scoring that prioritizes rankable keywords
        const volumeScore = Math.min(volume / 100, 50); // Cap at 50 to avoid over-prioritizing high volume
        const competitionScore = (1 - competition) * 40; // 40% weight on low competition
        const difficultyScore = Math.max(0, (50 - difficulty) / 50) * 30; // 30% weight on low difficulty
        const backlinkScore = Math.max(0, (100 - backlinks) / 100) * 20; // 20% weight on low backlink requirement
        const cpcScore = Math.min(cpc, 5) * 2; // 10% weight on commercial intent

        return Math.round(volumeScore + competitionScore + difficultyScore + backlinkScore + cpcScore);
    } catch (error) {
        console.error("Error in calculateOpportunityScore:", error);
        return 0;
    }
}

function getSeasonalPeak(monthlyData) {
    try {
        if (!monthlyData || monthlyData.length === 0) {
            return { month: 'N/A', year: 'N/A', volume: 0 };
        }

        const sorted = [...monthlyData].sort((a, b) => b.search_volume - a.search_volume);
        return {
            month: sorted[0].month,
            year: sorted[0].year,
            volume: sorted[0].search_volume
        };
    } catch (error) {
        console.error("Error in getSeasonalPeak:", error);
        return { month: 'N/A', year: 'N/A', volume: 0 };
    }
}

function analyzeMonthlTrends(monthlyData) {
    try {
        if (!monthlyData || monthlyData.length === 0) {
            return {
                summer_peak: 0,
                winter_low: 0,
                spring_buildup: 0
            };
        }

        return {
            summer_peak: monthlyData.filter(m => [5,6,7].includes(m.month)).reduce((sum, m) => sum + m.search_volume, 0),
            winter_low: monthlyData.filter(m => [11,12,1].includes(m.month)).reduce((sum, m) => sum + m.search_volume, 0),
            spring_buildup: monthlyData.filter(m => [3,4].includes(m.month)).reduce((sum, m) => sum + m.search_volume, 0)
        };
    } catch (error) {
        console.error("Error in analyzeMonthlTrends:", error);
        return { summer_peak: 0, winter_low: 0, spring_buildup: 0 };
    }
}

function getMostCommonCompetition(items) {
    try {
        const levels = items
            .filter(item => item.keyword_data?.keyword_info?.competition_level)
            .map(item => item.keyword_data.keyword_info.competition_level);

        if (levels.length === 0) return 'MEDIUM';

        const levelCounts = {};
        levels.forEach(level => {
            levelCounts[level] = (levelCounts[level] || 0) + 1;
        });

        return Object.keys(levelCounts).reduce((a, b) => levelCounts[a] > levelCounts[b] ? a : b);
    } catch (error) {
        console.error("Error in getMostCommonCompetition:", error);
        return 'MEDIUM';
    }
}

function identifyGaps(items) {
    try {
        const gaps = items
            .filter(item => {
                if (!item.keyword_data?.keyword_info) return false;
                return item.keyword_data.keyword_info.search_volume > 50 && 
                       item.keyword_data.keyword_info.competition < 0.3 &&
                       (item.keyword_data.keyword_properties?.keyword_difficulty || 0) < 20;
            })
            .map(item => ({
                keyword: item.keyword_data.keyword,
                searchVolume: item.keyword_data.keyword_info.search_volume,
                competition: item.keyword_data.keyword_info.competition_level,
                difficulty: item.keyword_data.keyword_properties?.keyword_difficulty || 0
            }));

        // Return all gaps if less than 5, otherwise top 5
        return gaps.slice(0, Math.min(5, gaps.length));
    } catch (error) {
        console.error("Error in identifyGaps:", error);
        return [];
    }
}

function getRecommendedTargets(items) {
    try {
        const targets = items
            .filter(item => {
                if (!item.keyword_data?.keyword_info) return false;

                // Multi-criteria targeting for best ranking opportunities
                const kw = item.keyword_data.keyword_info;
                const props = item.keyword_data.keyword_properties;
                const serp = item.keyword_data.serp_info;

                // Core ranking factors
                const hasGoodVolume = kw.search_volume >= 30 && kw.search_volume <= 1000;
                const hasLowCompetition = kw.competition < 0.5;
                const hasLowDifficulty = (props?.keyword_difficulty || 0) < 35;
                const hasLowBacklinks = (item.keyword_data.avg_backlinks_info?.backlinks || 0) < 30;

                // SERP feature opportunities
                const hasLocalPack = serp?.serp_item_types?.includes('local_pack');
                const hasFeaturedSnippet = serp?.serp_item_types?.includes('featured_snippet');
                const hasPAA = serp?.serp_item_types?.includes('people_also_ask');

                // Keyword characteristics
                const isLongTail = item.keyword_data.keyword.split(' ').length >= 4;
                const isQuestion = ['how', 'what', 'where', 'when', 'why'].some(q => 
                    item.keyword_data.keyword.toLowerCase().startsWith(q));

                // Score based on multiple factors
                let score = 0;
                if (hasGoodVolume) score += 2;
                if (hasLowCompetition) score += 3;
                if (hasLowDifficulty) score += 3;
                if (hasLowBacklinks) score += 2;
                if (hasLocalPack) score += 2;
                if (hasFeaturedSnippet || hasPAA) score += 1;
                if (isLongTail) score += 2;
                if (isQuestion) score += 1;

                return score >= 6; // Need at least 6 points to be a good target
            })
            .sort((a, b) => {
                // Sort by opportunity score
                const scoreA = calculateOpportunityScore(a.keyword_data);
                const scoreB = calculateOpportunityScore(b.keyword_data);
                return scoreB - scoreA;
            })
            .map(item => ({
                keyword: item.keyword_data.keyword,
                volume: item.keyword_data.keyword_info.search_volume,
                difficulty: item.keyword_data.keyword_properties?.keyword_difficulty || 0,
                competition: item.keyword_data.keyword_info.competition,
                whyRecommended: determineWhyRecommended(item)
            }));

        // Return all targets if less than 8, otherwise top 8
        return targets.slice(0, Math.min(8, targets.length));
    } catch (error) {
        console.error("Error in getRecommendedTargets:", error);
        return [];
    }
}

function determineWhyRecommended(item) {
    try {
        const reasons = [];
        const kw = item.keyword_data.keyword_info;
        const props = item.keyword_data.keyword_properties;

        if (kw.competition < 0.3) reasons.push("Very low competition");
        if ((props?.keyword_difficulty || 0) < 25) reasons.push("Low difficulty");
        if (item.keyword_data.keyword.split(' ').length >= 4) reasons.push("Long-tail keyword");
        if ((item.keyword_data.avg_backlinks_info?.backlinks || 0) < 20) reasons.push("Low backlink requirement");
        if (item.keyword_data.serp_info?.serp_item_types?.includes('local_pack')) reasons.push("Local pack opportunity");

        return reasons.join(", ") || "Good ranking potential";
    } catch (error) {
        console.error("Error in determineWhyRecommended:", error);
        return "Good ranking potential";
    }
}

function generateSupportingContentIdeas(clusters) {
    // Legacy function - replaced by generateUniversalContentIdeas
    return generateUniversalContentIdeas(clusters, "service");
}

function identifySnippetOpportunities(items) {
    try {
        const snippets = items
            .filter(item => item.keyword_data?.serp_info?.serp_item_types?.includes('featured_snippet'))
            .map(item => ({
                keyword: item.keyword_data.keyword,
                currentFeature: 'featured_snippet',
                volume: item.keyword_data.keyword_info?.search_volume || 0
            }));

        return snippets;
    } catch (error) {
        console.error("Error in identifySnippetOpportunities:", error);
        return [];
    }
}

function extractPAAQuestions(items) {
    try {
        const questions = items
            .filter(item => item.keyword_data?.serp_info?.serp_item_types?.includes('people_also_ask'))
            .map(item => item.keyword_data.keyword);

        // Return all questions if less than 10, otherwise top 10
        return questions.slice(0, Math.min(10, questions.length));
    } catch (error) {
        console.error("Error in extractPAAQuestions:", error);
        return [];
    }
}

// MAIN EXECUTION FOR N8N
try {
    // Get all input items from n8n
    const inputData = $input.all();
    const results = [];

    console.log("Processing " + inputData.length + " items");

    // Process each input item
    for (const item of inputData) {
        try {
            // Debug: Check what we're getting from n8n
            console.log("Processing item:", JSON.stringify(Object.keys(item), null, 2));

            // Try different possible data locations
            let dataForSEOResponse;

            if (item.json && Array.isArray(item.json)) {
                dataForSEOResponse = item.json;
            } else if (item.json) {
                dataForSEOResponse = [item.json];
            } else {
                dataForSEOResponse = [item];
            }

            const processedData = processRelatedKeywords(dataForSEOResponse);

            // Add the processed data to results
            results.push({
                json: processedData
            });
        } catch (error) {
            console.error("Error processing item:", error);
            // Return error information for debugging
            results.push({
                json: {
                    error: error.message,
                    errorStack: error.stack,
                    inputStructure: Object.keys(item),
                    itemJsonStructure: item.json ? Object.keys(item.json) : "No json property"
                }
            });
        }
    }

    // Return the array of objects that n8n expects
    return results;
} catch (error) {
    console.error("Fatal error in main execution:", error);
    return [{
        json: {
            error: "Fatal error: " + error.message,
            errorStack: error.stack
        }
    }];
}

