// --- Get Input Data ---
// Get the single input item from the previous node.
const item = $input.item;

// Get the user-selected country and language from the input JSON.
const userCountry = item.json["What country are you targeting?"];
const userLanguage = item.json["What language should the content be in?"];


// --- SECTION 1: SERPAPI PARAMETER CONVERSION ---

// Mapping of form country names to SerpApi 'gl' country codes.
