// Script designed for the specific n8n structure we can see in the debug output
// This handles the actual structure: $input.item.json.output and $input.all() for multiple items

try {
  let result = {
    debug_info: {},
    success: false,
    error: null
  };

  // Get all items from the merge node
  const allItems = $input.all();

  result.debug_info.total_items = allItems.length;
  result.debug_info.all_items_structure = allItems.map((item, index) => ({
    index,
    has_json: !!item.json,
    has_output: !!(item.json && item.json.output),
    keys: item.json ? Object.keys(item.json) : []
  }));

  if (allItems.length < 2) {
    result.error = `Expected 2 items from merge node, got ${allItems.length}`;
    return result;
  }

  // Extract article data from first item
  const firstItem = allItems[0];
  let articleData = null;

  if (firstItem.json && firstItem.json.output) {
    articleData = firstItem.json.output;
    result.debug_info.article_source = 'firstItem.json.output';
  } else if (firstItem.json) {
    articleData = firstItem.json;
    result.debug_info.article_source = 'firstItem.json';
  }

  // Extract citation data from second item
  const secondItem = allItems[1];
  let citationData = null;

  if (secondItem.json && secondItem.json.output) {
    citationData = secondItem.json.output;
    result.debug_info.citation_source = 'secondItem.json.output';
  } else if (secondItem.json) {
    citationData = secondItem.json;
    result.debug_info.citation_source = 'secondItem.json';
  }

  result.debug_info.article_data_found = !!articleData;
  result.debug_info.citation_data_found = !!citationData;
  result.debug_info.article_has_body = !!(articleData && articleData.body);
  result.debug_info.citation_has_citations = !!(citationData && citationData.authoritative_citations);

  // Log what we found
  if (articleData) {
    result.debug_info.article_keys = Object.keys(articleData);
  }
  if (citationData) {
    result.debug_info.citation_keys = Object.keys(citationData);
  }

  // Check if we have all required data
  if (!articleData || !articleData.body) {
    result.error = 'Missing article data or body';
    return result;
  }

  if (!citationData || !citationData.authoritative_citations) {
    result.error = 'Missing citation data or authoritative_citations';
    return result;
  }

  // Process the citations
  const { Title, toc, body, meta_description } = articleData;
  const citations = citationData.authoritative_citations;

  // Remove the title from the body (assumes title is an H1 at the beginning)
  let modifiedBody = body;

  // Remove H1 title if it exists at the start of the body
  if (Title && modifiedBody.startsWith(`# ${Title}`)) {
    modifiedBody = modifiedBody.replace(`# ${Title}`, '').trim();
  }
  // Also handle case where there might be extra newlines after title removal
  modifiedBody = modifiedBody.replace(/^\n+/, '');
  let replacements = [];

  for (let i = 0; i < citations.length; i++) {
    const citation = citations[i];

    if (citation.suggested_anchor_text && citation.url) {
      const findText = citation.suggested_anchor_text;
      const replaceText = `<a href="${citation.url}" target="_blank" rel="noopener noreferrer">${findText}</a>`;

      if (modifiedBody.includes(findText)) {
        // Replace only the first occurrence
        const index = modifiedBody.indexOf(findText);
        modifiedBody = modifiedBody.substring(0, index) + replaceText + modifiedBody.substring(index + findText.length);

        replacements.push({
          index: i + 1,
          text: findText,
          url: citation.url,
          success: true
        });
      } else {
        replacements.push({
          index: i + 1,
          text: findText,
          url: citation.url,
          success: false,
          reason: 'Text not found in body'
        });
      }
    } else {
      replacements.push({
        index: i + 1,
        success: false,
        reason: 'Missing anchor text or URL',
        citation: citation
      });
    }
  }

  result.success = true;
  result.debug_info.citations_processed = citations.length;
  result.debug_info.successful_replacements = replacements.filter(r => r.success).length;
  result.debug_info.replacement_details = replacements;

  // Return the processed article
  return {
    Title,
    toc,
    body: modifiedBody,
    meta_description,
    debug_info: result.debug_info
  };

} catch (error) {
  return {
    success: false,
    error: error.message,
    stack: error.stack,
    debug_info: {
      error_occurred: true,
      error_message: error.message
    }
  };
}

// Robust HTML formatter that adapts to different content structures
// Handles various heading arrangements, missing sections, and flexible FAQ detection

// Get the input data from n8n
const inputItems = $input.all();

// Function to recursively search for article data in nested objects
function findArticleData(obj, depth = 0) {
  if (depth > 10) return null;

  if (obj && typeof obj === 'object' && obj.Title && obj.body) {
    return obj;
  }

  if (Array.isArray(obj) && obj.length > 0) {
    return findArticleData(obj[0], depth + 1);
  }

  if (obj && typeof obj === 'object') {
    const commonKeys = ['output', 'data', 'article', 'content', 'result', 'response'];

    for (const key of commonKeys) {
      if (obj[key]) {
        const found = findArticleData(obj[key], depth + 1);
        if (found) return found;
      }
    }

    for (const [key, value] of Object.entries(obj)) {
      if (!commonKeys.includes(key)) {
        const found = findArticleData(value, depth + 1);
        if (found) return found;
      }
    }
  }

  return null;
}

// Helper function to create safe anchor IDs
function createAnchorId(text) {
  return text.toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

// Helper function to detect FAQ-like content patterns
function detectFAQPattern(content) {
  // Look for various Q&A patterns
  const patterns = [
    /<p><strong>Q:\s*(.*?)<\/strong><br>A:\s*(.*?)<\/p>/gi,
    /<p><strong>(.*?\?)<\/strong><br>(.*?)<\/p>/gi,
    /<p><strong>(How|What|When|Where|Why|Do|Can|Is|Are).*?\?<\/strong><br>(.*?)<\/p>/gi
  ];

  for (const pattern of patterns) {
    if (pattern.test(content)) {
      return pattern;
    }
  }
