  let articleData = findArticleData(inputData);

  if (!articleData) {
    if (inputData.Title && inputData.body) {
      articleData = inputData;
    } else {
      console.log('Unable to find Title and body in structure:', JSON.stringify(inputData, null, 2));
      throw new Error('Could not find article data with Title and body properties');
    }
  }

  const { Title, body, toc } = articleData;
  let htmlBody = body;
  let tocHTML = '';

  // Generate TOC if it exists and has content
  if (toc && Array.isArray(toc) && toc.length > 0) {
    tocHTML = '<div class="table-of-contents" style="margin: 30px 0; padding: 20px; background-color: #f9f9f9; border-left: 4px solid #007cba;">\n<h2 style="margin-top: 0;">Table of Contents</h2>\n<ul style="margin-bottom: 0;">\n';
    toc.forEach(item => {
      const anchor = createAnchorId(item);
      tocHTML += `  <li style="margin-bottom: 5px;"><a href="#${anchor}" style="color: #007cba; text-decoration: none;">${item}</a></li>\n`;
    });
    tocHTML += '</ul>\n</div>\n\n';
  }

  // Remove title from body (flexible patterns)
  htmlBody = htmlBody.replace(/^#\s*.*?\n?/, '');
  htmlBody = htmlBody.replace(/^\s+/, '');

  // Convert headers with flexible anchor creation
  htmlBody = htmlBody.replace(/^#{4,6}\s+(.+)$/gm, '<h4>$1</h4>');
  htmlBody = htmlBody.replace(/^###\s+(.+)$/gm, '<h3>$1</h3>');
  htmlBody = htmlBody.replace(/^##\s+(.+)$/gm, (match, title) => {
    const anchor = createAnchorId(title);
    return `<h2 id="${anchor}">${title}</h2>`;
  });
  htmlBody = htmlBody.replace(/^#\s+(.+)$/gm, '<h1>$1</h1>');

  // Convert formatting
  htmlBody = htmlBody.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  htmlBody = htmlBody.replace(/\*(.+?)\*/g, '<em>$1</em>');

  // Convert lists (flexible spacing)
  htmlBody = htmlBody.replace(/^\*\s+(.+)$/gm, '<li>$1</li>');
  htmlBody = htmlBody.replace(/(<li>.*?<\/li>(?:\s*<li>.*?<\/li>)*)/gs, '<ul>$1</ul>');

  // Convert various link formats
  htmlBody = htmlBody.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');

  // Internal links
  htmlBody = htmlBody.replace(/(\w+(?:\s+\w+){1,3})\s+\[link-to:([^\]]+)\]/g, '<a href="#" rel="internal">$1</a>');
  htmlBody = htmlBody.replace(/\[link-to:([^\]]+)\]/g, '<a href="#" rel="internal">$1</a>');

  // Fix: Better pattern for standalone URLs with proper anchor text capture
  // This captures longer phrases (up to 8 words) before the URL bracket
  htmlBody = htmlBody.replace(/(\w+(?:\s+\w+){0,7})\s+\[([^\]]*https?:\/\/[^\]]+)\]/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
  htmlBody = htmlBody.replace(/\[([^\]]*https?:\/\/[^\]]+)\]/g, '<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>');

  // Phone numbers (comprehensive handling)
  htmlBody = htmlBody.replace(/(\(\d{3}\)\s?\d{3}-\d{4})\s*\[tel:([^\]]+)\]/g, '<a href="tel:$2">$1</a>');
  htmlBody = htmlBody.replace(/\[tel:([^\]]+)\]/g, (match, phoneNumber) => {
    const displayNumber = phoneNumber.replace(/^\+1-/, '');
    return `<a href="tel:${phoneNumber}">${displayNumber}</a>`;
  });
  htmlBody = htmlBody.replace(/(\(\d{3}\)\s?\d{3}-\d{4})/g, '<a href="tel:$1">$1</a>');

  // Convert to paragraphs
  const paragraphs = htmlBody.split(/\n\s*\n/);
  htmlBody = paragraphs.map(paragraph => {
    paragraph = paragraph.trim();
    if (!paragraph) return '';
    if (paragraph.match(/^<(h[1-6]|ul|ol|li|div|blockquote)/i)) {
      return paragraph;
    }
    // Fix: Better image suggestion detection and conversion
    if (paragraph.match(/^\[Image Suggestion:/i)) {
      return `<!-- ${paragraph} -->`;
    }
    paragraph = paragraph.replace(/\n/g, '<br>');
    return `<p>${paragraph}</p>`;
  }).filter(p => p).join('\n\n');

  // Flexible FAQ detection and conversion
  htmlBody = htmlBody.replace(/(<h2 id="[^"]*">.*?(?:faq|question|q&a|help).*?<\/h2>)([\s\S]*?)(?=<h2|$)/gi, (match, h2, faqContent) => {
    const faqPattern = detectFAQPattern(faqContent);

    if (faqPattern) {
      const accordionItems = faqContent.replace(faqPattern, (pMatch, question, answer) => {
        question = question.trim();
        answer = answer.trim();

        return `
<details style="border-bottom: 1px solid #e0e0e0; padding: 15px 5px; margin-bottom: 5px;">
  <summary style="font-weight: 600; font-size: 1.1em; cursor: pointer; outline: none; list-style-position: inside;">${question}</summary>
  <p style="margin-top: 15px; padding: 0 10px; color: #333; line-height: 1.6;">${answer}</p>
</details>`;
      });

      if (accordionItems !== faqContent) {
        return h2 + '\n' + accordionItems;
      }
    }

    return match; // Return original if no FAQ pattern detected
  });

  // Cleanup
  htmlBody = htmlBody.replace(/>\s+</g, '><');
  htmlBody = htmlBody.replace(/<\/ul>\s*<ul>/g, '');
  htmlBody = htmlBody.replace(/<\/li><\/li>/g, '</li>');
  htmlBody = htmlBody.replace(/<li><\/li>/g, '');
  htmlBody = htmlBody.replace(/<p>(<(h[1-6]|ul|ol|div|blockquote|details)[^>]*>.*?<\/\2>)<\/p>/gs, '$1');
  htmlBody = htmlBody.replace(/(<\/(p|h[1-6]|ul|ol|div|blockquote|details)>)/g, '$1\n');
  htmlBody = htmlBody.trim();

  // Smart TOC insertion with multiple fallbacks
  let finalHTML = htmlBody;
  if (tocHTML) {
    const firstParagraphEnd = finalHTML.indexOf('</p>');

    if (firstParagraphEnd !== -1) {
      // Insert after first paragraph
      const insertPosition = firstParagraphEnd + 5;
      finalHTML = finalHTML.slice(0, insertPosition) + '\n' + tocHTML + finalHTML.slice(insertPosition);
    } else {
      // Try after first heading
      const firstHeadingEnd = finalHTML.search(/<\/h[1-6]>/);
      if (firstHeadingEnd !== -1) {
        const headingEndTag = finalHTML.match(/<\/h[1-6]>/)[0];
        const insertPosition = firstHeadingEnd + headingEndTag.length;
        finalHTML = finalHTML.slice(0, insertPosition) + '\n' + tocHTML + finalHTML.slice(insertPosition);
      } else {
        // Insert at beginning as last resort
        finalHTML = tocHTML + finalHTML;
      }
    }
  }

  return {
    json: {
      title: Title,
      html: finalHTML
    }
  };
});

return results;

