            <div class="section">
                <div class="section-header">
                    <h2>🎯 Search Intent Analysis</h2>
                    <span class="toggle">▼</span>
                </div>
                <div class="section-content">
                    <div class="analysis-text">${markdownToHtml(searchIntentAnalysis)}</div>
                </div>
            </div>
            ` : ''}

            <!-- Content Silo Strategy Section -->
            ${contentSiloStrategy ? `
            <div class="section">
                <div class="section-header">
                    <h2>📚 Content Silo Strategy</h2>
                    <span class="toggle">▼</span>
                </div>
                <div class="section-content">
                    <div class="analysis-text">${formatContentSiloStrategy(contentSiloStrategy)}</div>
                </div>
            </div>
            ` : ''}

            <!-- Draft Articles Section -->
            ${draftArticles.length > 0 ? `
            <div class="section active">
                <div class="section-header">
                    <h2>📝 Content Calendar & Draft Articles</h2>
                    <span class="toggle">▼</span>
                </div>
                <div class="section-content">
                    ${draftArticles.map(article => `
                    <div class="article-card">
                        <div class="article-header">
                            <h3>${article.content_title}</h3>
                            <span class="article-day">Day ${article.day}</span>
                        </div>

                        <div class="article-meta">
                            <span class="meta-tag">Type: ${article.content_type}</span>
                            <span class="meta-tag">Goal: ${article.primary_goal.split('.')[0]}</span>
                        </div>

                        <div class="keywords-list">
                            <h4>Target Keywords:</h4>
                            ${(() => {
                                try {
                                    const keywords = typeof article.target_keywords === 'string' 
                                        ? JSON.parse(article.target_keywords) 
                                        : article.target_keywords;

                                    if (Array.isArray(keywords)) {
                                        return keywords.map(keyword => 
                                            `<span class="keyword-tag">${keyword}</span>`
                                        ).join('');
                                    }
                                    return `<span class="keyword-tag">${article.target_keywords}</span>`;
                                } catch (e) {
                                    return `<span class="keyword-tag">${article.target_keywords}</span>`;
                                }
                            })()}
                        </div>

                        ${article.title ? `
                        <div class="info-box" style="margin-top: 15px;">
                            <h4>Article Details:</h4>
                            <p><strong>Title:</strong> ${article.title}</p>
                            <p><strong>Meta Description:</strong> ${article.meta_description}</p>
                        </div>
                        ` : ''}
                    </div>
                    `).join('')}
                </div>
            </div>
            ` : ''}
        </div>

        <div class="footer">
            Generated on ${new Date().toLocaleString()} • SEO Analysis Report for ${companyName}
        </div>
    </div>

    <script>
        // Toggle sections
        document.querySelectorAll('.section-header').forEach(header => {
            header.addEventListener('click', () => {
                const section = header.parentElement;
                section.classList.toggle('active');
            });
        });

        // Auto-expand certain sections
        document.querySelectorAll('.section').forEach((section, index) => {
            if (index === 0) {
                section.classList.add('active');
            }
        });
    </script>
</body>
</html>
  `;

  return htmlReport;
}

// Helper function to convert markdown to HTML
function markdownToHtml(text) {
  if (!text) return '';

  // Convert headers
  text = text.replace(/^#### (.*$)/gim, '<h4>$1</h4>');
  text = text.replace(/^### (.*$)/gim, '<h3>$1</h3>');
  text = text.replace(/^## (.*$)/gim, '<h2 style="color: #ff8e53; margin: 20px 0 10px 0;">$1</h2>');
  text = text.replace(/^# (.*$)/gim, '<h1>$1</h1>');

  // Convert bold and italic
  text = text.replace(/\*\*\*(.*)\*\*\*/g, '<strong><em>$1</em></strong>');
  text = text.replace(/\*\*(.*)\*\*/g, '<strong>$1</strong>');
  text = text.replace(/\*(.*)\*/g, '<em>$1</em>');

  // Convert bullet points
  text = text.replace(/^\* (.+)$/gim, '<li>$1</li>');
  text = text.replace(/(<li>.*<\/li>)/s, function(match) {
    return '<ul style="margin: 10px 0; padding-left: 20px;">' + match + '</ul>';
  });

  // Fix nested lists
  text = text.replace(/<\/ul>\s*<ul[^>]*>/g, '');

  // Convert numbered lists
  text = text.replace(/^\d+\. (.+)$/gim, '<li>$1</li>');
  text = text.replace(/(<li>.*<\/li>)(?!.*<\/ul>)/s, function(match) {
    if (!match.includes('<ul')) {
      return '<ol style="margin: 10px 0; padding-left: 20px;">' + match + '</ol>';
    }
    return match;
  });

  // Convert line breaks to paragraphs
  const paragraphs = text.split(/\n\n+/);
  text = paragraphs.map(para => {
    para = para.trim();
    if (para && !para.startsWith('<') && !para.match(/^[\*\d]+\./)) {
      return `<p style="margin-bottom: 15px; line-height: 1.8;">${para}</p>`;
    }
    return para;
  }).join('\n');

  // Convert single line breaks
  text = text.replace(/\n/g, '<br>');

  // Style lists
  text = text.replace(/<ul/g, '<ul style="margin: 15px 0; padding-left: 25px; list-style-type: disc;"');
  text = text.replace(/<ol/g, '<ol style="margin: 15px 0; padding-left: 25px;"');
  text = text.replace(/<li>/g, '<li style="margin-bottom: 8px; color: #b0b0b0;">');

  return text;
}

// Helper function to format content silo strategy
function formatContentSiloStrategy(strategyJson) {
  try {
    const strategy = typeof strategyJson === 'string' ? JSON.parse(strategyJson) : strategyJson;
    if (strategy && strategy.one_week_content_campaign) {
      const campaign = strategy.one_week_content_campaign;
      let formatted = `<h3 style="color: #ff8e53; margin-bottom: 15px;">Campaign Focus</h3>\n<p style="margin-bottom: 20px; line-height: 1.8;">${campaign.campaign_focus}</p>\n\n<h3 style="color: #ff8e53; margin-bottom: 15px;">Content Plan</h3>\n`;

      if (campaign.content_plan && Array.isArray(campaign.content_plan)) {
        campaign.content_plan.forEach(item => {
          formatted += `\n<div style="background-color: #3a3a3a; padding: 20px; border-radius: 8px; margin-bottom: 15px; border-left: 4px solid #ff6b6b;">`;
          formatted += `<h4 style="color: #ff8e53; margin-bottom: 10px;">Day ${item.day}: ${item.content_title}</h4>\n`;
          formatted += `<p style="margin-bottom: 8px;"><strong style="color: #e0e0e0;">Type:</strong> ${item.content_type}</p>\n`;
          formatted += `<p style="margin-bottom: 8px;"><strong style="color: #e0e0e0;">Goal:</strong> ${item.primary_goal}</p>\n`;
          formatted += `<p><strong style="color: #e0e0e0;">Keywords:</strong> ${item.target_keywords.join(', ')}</p>\n`;
          formatted += `</div>`;
        });
      }

      return formatted;
    }
  } catch (e) {
    // If parsing fails, return the original string with markdown conversion
  }
  return markdownToHtml(strategyJson);
}

// Main execution for N8N
const inputData = $input.all();
const reportData = inputData[0].json;

// Generate the HTML report
const htmlOutput = generateSEOReport(reportData);

// Return the HTML for N8N
return [{
  json: {
    html: htmlOutput,
    timestamp: new Date().toISOString(),
    reportType: 'SEO Analysis Report'
  }
}];

