parameters.jsCode:
// n8n Code Node - Transform SEO & Keyword Research Data to HTML Report (v21 - Final Formatting)

// --- HELPER & VISUALIZATION FUNCTIONS ---

function createSection(title, content) {
  if (!content || content.trim() === '') return '';
  return `<div class="section"><div class="section-header" onclick="toggleSection(this)"><h2>${title}</h2><span class="toggle-icon">+</span></div><div class="section-content">${content}</div></div>`;
}

function createCard(title, content, cardClass = '') {
  if (!content || content.trim() === '') return '';
  return `<div class="card ${cardClass}"><div class="card-header"><h3>${title}</h3></div><div class="card-content">${content}</div></div>`;
}

function createKeyValueList(dataObject) {
    if (!dataObject) return '';
    let content = '<div class="key-value-grid">';
    for (const [key, value] of Object.entries(dataObject)) {
        if (value && typeof value === 'object' && 'count' in value) {
            const formattedKey = key.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
            const displayValue = `${value.count} instances (${value.percentage}%)`;
            const opportunityText = value.opportunity ? `<br><small>${value.opportunity}</small>` : '';
            content += `<div class="kv-item"><span class="kv-key">${formattedKey}</span><span class="kv-value">${displayValue}${opportunityText}</span></div>`;
        } else if (value) {
            const formattedKey = key.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
            content += `<div class="kv-item"><span class="kv-key">${formattedKey}</span><span class="kv-value">${renderTag(value.toString())}</span></div>`;
        }
    }
    return content + '</div>';
}

function renderTag(value) {
    if (typeof value !== 'string') return value ?? 'N/A';
    const lowerValue = value.toLowerCase();
    let className = 'tag-default';
    if (['high', 'critical', 'very high'].includes(lowerValue)) className = 'tag-high';
    else if (['medium'].includes(lowerValue)) className = 'tag-medium';
    else if (['low', 'very low'].includes(lowerValue)) className = 'tag-low';
    return `<span class="tag ${className}">${value}</span>`;
}

function renderPriorityTag(value) {
    if (typeof value !== 'string') return value ?? 'N/A';
    const lowerValue = value.toLowerCase();
    let className = 'tag-opportunity-low'; // Default to yellow
    if (['high', 'critical'].includes(lowerValue) || value === 1) className = 'tag-opportunity-high';
    else if (['medium'].includes(lowerValue) || value === 2) className = 'tag-opportunity-medium';
    return `<span class="tag ${className}">${value}</span>`;
}

function renderScore(value) {
    const num = parseInt(value, 10);
    if (isNaN(num)) return value;
    let className = 'tag-low'; // Default to green for low difficulty
    if (num > 70) className = 'tag-high';
    else if (num > 40) className = 'tag-medium';
    return `<span class="tag ${className}">${value}</span>`;
}

function renderOpportunityScore(value) {
    const num = parseInt(value, 10);
    if (isNaN(num)) return value;
    let className = 'tag-high'; // Default to Red for low opportunity
    if (num > 75) className = 'tag-low'; // Green for high opportunity
    else if (num > 40) className = 'tag-medium'; // Yellow for medium
    return `<span class="tag ${className}">${value}</span>`;
}

function createTable(data, columns, customRenderers = {}) {
  if (!data || !Array.isArray(data) || data.length === 0) return '<p>No data available.</p>';
  const headers = columns.map(col => `<th>${col.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())}</th>`).join('');
  const rows = data.map(row => {
    const cells = columns.map(col => {
      const cellValue = row[col];
      let cellContent = Array.isArray(cellValue) ? cellValue.join('<br>') : (cellValue ?? 'N/A');
      if (customRenderers[col]) {
        cellContent = customRenderers[col](cellValue, row);
      }
      return `<td>${cellContent}</td>`;
    }).join('');
    return `<tr>${cells}</tr>`;
  }).join('');
  return `<div class="table-container"><table><thead><tr>${headers}</tr></thead><tbody>${rows}</tbody></table></div>`;
}

// --- CHART & DATA PREPARATION ---

let chartsToRender = [];

function prepareContentClusterChart(clustersData) {
    if (!clustersData) return;
    const labels = Object.keys(clustersData).map(k => k.replace(/_/g, ' '));
    const data = Object.values(clustersData).map(c => c.totalSearchVolume);
    chartsToRender.push({
        id: 'contentClusterChart', type: 'bar', title: 'Search Volume by Content Cluster',
        data: { labels, datasets: [{ label: 'Total Search Volume', data, backgroundColor: '#ff6b35' }] },
        options: { indexAxis: 'y' }
    });
}

function prepareSearchIntentChart(keywords) {
    if (!keywords || keywords.length === 0) return;
    const intentCounts = keywords.reduce((acc, kw) => {
        const intent = kw.primary_intent;
        if(intent) acc[intent] = (acc[intent] || 0) + 1;
        return acc;
    }, {});
    const labels = Object.keys(intentCounts).map(k => k.charAt(0).toUpperCase() + k.slice(1));
    const data = Object.values(intentCounts);
    chartsToRender.push({
        id: 'searchIntentChart', type: 'pie', title: 'Primary Intent Distribution',
        data: { labels, datasets: [{ data, backgroundColor: ['#ff6b35', '#4a9eff', '#3cba92', '#c45850', '#e8c3b9'] }] }
    });
}

function renderChartsScript() {
    if (chartsToRender.length === 0) return '';
    return chartsToRender.map(chart => `
        try {
            if (document.getElementById('${chart.id}')) {
                new Chart(document.getElementById('${chart.id}'), {
                    type: '${chart.type}',
                    data: ${JSON.stringify(chart.data)},
                    options: { responsive: true, maintainAspectRatio: false, plugins: { title: { display: true, text: '${chart.title}', color: '#e0e0e0', font: { size: 16 } }, legend: { labels: { color: '#e0e0e0' } } },
                        scales: ${chart.type === 'bar' ? `{ y: { ticks: { color: '#e0e0e0' } }, x: { ticks: { color: '#e0e0e0' } } }` : `{}`},
                        ...${JSON.stringify(chart.options || {})}
                    }
                });
            }
        } catch (e) { console.error('Error rendering chart ' + chart.id + ':', e); }
    `).join('\n');
}

// --- SECTION RENDERING FUNCTIONS ---

function renderSerpAnalysis(serpData, title) {
  if (!serpData) return '';
  let content = '<div class="card-deck">';

  let topGridContent = '';
  if (serpData.overview) {
    topGridContent += createCard('Overview', `<p><strong>Keyword:</strong> ${serpData.overview.keyword}</p><p><strong>Competition:</strong> ${renderTag(serpData.overview.competition)}</p><p><strong>Total Results:</strong> ${serpData.overview.totalResults ? serpData.overview.totalResults.toLocaleString() : 'N/A'}</p>`);
  }
  if (serpData.aiOverview?.opportunities?.length > 0) {
      topGridContent += createCard('AI Overview Opportunities', createTable(serpData.aiOverview.opportunities, ['type', 'opportunity', 'action', 'priority'], { 'priority': renderPriorityTag, 'type': renderTag }));
  }
  if (serpData.insights) {
      let insightsContent = `<p><strong>Main Opportunity:</strong> ${serpData.insights.mainOpportunity || 'N/A'}</p>`;
      insightsContent += `<p><strong>Recommended Focus:</strong> ${serpData.insights.recommendedFocus || 'N/A'}</p>`;
      insightsContent += `<p><strong>Quick Win Count:</strong> ${serpData.insights.quickWinCount || 'N/A'}</p>`;
      topGridContent += createCard('Insights', insightsContent);
  }
   if (serpData.strategy?.reasoning?.length > 0) {
      topGridContent += createCard('Strategy Reasoning', `<ul>${serpData.strategy.reasoning.map(r => `<li>${r}</li>`).join('')}</ul>`);
  }

  if (topGridContent) {
      // Use a grid for Bing, but stack for Google to prevent squishing
      const gridClass = title.includes('Bing') ? 'two-col-grid' : '';
      content += `<div class="${gridClass}">${topGridContent}</div>`;
  }

  if (serpData.opportunities?.length > 0) {
      content += createCard('Bing Opportunities', createTable(serpData.opportunities, ['type', 'impact', 'description', 'action', 'priority'], { 'priority': renderPriorityTag, 'impact': renderTag }), 'card-full-width');
  }

  if (serpData.strategy?.topPriority) {
      let strategyContent = '';
      const priorities = ['topPriority', 'secondPriority', 'thirdPriority'];
      priorities.forEach(p => {
          if (serpData.strategy[p]) {
              const item = serpData.strategy[p];
              strategyContent += `<h4>${p.replace('Priority', ' Priority')}</h4><p>${item.description}</p><p><strong>Action:</strong> ${item.action}</p>`;
          }
      });
      content += createCard('Strategy Priorities', strategyContent, 'card-full-width');
  }

  if (serpData.content?.priorityQuestions?.length > 0) {
    content += createCard('Priority Questions', createTable(serpData.content.priorityQuestions, ['question', 'contentType', 'commercialIntent', 'priority'], { 'priority': renderPriorityTag }), 'card-full-width');
  }
  if (serpData.content?.contentGaps?.length > 0) {
    content += createCard('Content Gaps', createTable(serpData.content.contentGaps, ['topic', 'reason', 'contentType', 'priority'], { 'priority': renderPriorityTag }), 'card-full-width');
  }
  if (serpData.actions) {
      let actionContent = '';
      if (serpData.actions.immediate) actionContent += '<h3>Immediate</h3><ul>' + serpData.actions.immediate.map(i => `<li>${i}</li>`).join('') + '</ul>';
      if (serpData.actions.week1) actionContent += '<h3>Week 1</h3><ul>' + serpData.actions.week1.map(i => `<li>${i}</li>`).join('') + '</ul>';
      if (serpData.actions.month1) actionContent += '<h3>Month 1</h3><ul>' + serpData.actions.month1.map(i => `<li>${i}</li>`).join('') + '</ul>';
      content += createCard('Action Plan', actionContent, 'card-full-width');
  }

  if (title.includes('Bing') && serpData.quickWins?.length > 0) {
     const filteredWins = serpData.quickWins.filter(win => !win.domain.includes('youtube.com'));
     if(filteredWins.length > 0) {
        content += createCard('Quick Wins', createTable(filteredWins, ['position', 'domain', 'opportunity', 'weaknesses', 'difficulty'], { 'difficulty': renderTag }), 'card-full-width');
     }
  }
  content += '</div>';
  return createSection(title, content);
}

function renderRelatedKeywords(relatedData) {
    if (!relatedData) return '';
    let content = '<div class="card-deck">';
    if (relatedData.primaryKeywordData) {
        const pkd = relatedData.primaryKeywordData;
        const seasonality = pkd.seasonality?.trend?.yearly > 0 ? '▲' : '▼';
        let pkdContent = `<p><strong>Search Volume:</strong> ${pkd.searchVolume.toLocaleString()}</p>`;
        pkdContent += `<p><strong>CPC:</strong> $${pkd.cpc}</p>`;
        pkdContent += `<p><strong>Competition:</strong> ${renderTag(pkd.competition)}</p>`;
        pkdContent += `<p><strong>Difficulty:</strong> ${renderScore(pkd.difficulty)}</p>`;
        pkdContent += `<p><strong>Yearly Trend:</strong> ${seasonality} ${pkd.seasonality?.trend?.yearly}%</p>`;
        content += createCard(`Primary Keyword: "${pkd.keyword}"`, pkdContent, 'card-full-width');
    }
    if (relatedData.highValueKeywords?.length > 0) {
        prepareContentClusterChart(relatedData.contentClusters);
        content += createCard('High-Value Keywords', createTable(relatedData.highValueKeywords, ['keyword', 'searchVolume', 'cpc', 'difficulty', 'intent', 'opportunity'], {
            'difficulty': renderScore, 'intent': renderTag, 'opportunity': renderOpportunityScore
        }), 'card-full-width');
    }
    if (relatedData.competitorAnalysis?.recommendedTargets?.length > 0) {
        content += createCard('Recommended Competitor Targets', createTable(relatedData.competitorAnalysis.recommendedTargets, ['keyword', 'volume', 'difficulty', 'competition', 'whyRecommended']), 'card-full-width');
    }
    if (relatedData.contentClusters) {
        content += createCard('Content Clusters Chart', `<div class="chart-container" style="height: 300px;"><canvas id="contentClusterChart"></canvas></div>`, 'card-full-width');
    }
    content += '</div>';
    return createSection('Related Keywords Analysis', content);
}

function renderKeywordIdeas(keywordIdeasData) {
    if (!keywordIdeasData) return '';
    let content = '<div class="card-deck">';

    if (keywordIdeasData.campaign?.marketInsights) {
        content += createCard('Market Insights', `<p>${keywordIdeasData.campaign.marketInsights.join('</p><p>')}</p>`, 'card-full-width');
    }

    let opportunityMatrixContent = '';
    if (keywordIdeasData.opportunityMatrix?.quickWins?.length > 0) {
        opportunityMatrixContent += createCard('Quick Win Keywords', createTable(keywordIdeasData.opportunityMatrix.quickWins, ['keyword', 'searchVolume', 'cpc', 'competition', 'opportunityScore', 'intent'], { 'competition': renderTag, 'intent': renderTag, 'opportunityScore': renderOpportunityScore }));
    }
    if (keywordIdeasData.opportunityMatrix?.highValue?.length > 0) {
        opportunityMatrixContent += createCard('High Value Keywords', createTable(keywordIdeasData.opportunityMatrix.highValue, ['keyword', 'searchVolume', 'cpc', 'monthlyValue', 'competition', 'intent'], { 'competition': renderTag, 'intent': renderTag }));
    }
    if (keywordIdeasData.opportunityMatrix?.local?.keywords?.length > 0) {
        opportunityMatrixContent += createCard('Local Opportunities', createTable(keywordIdeasData.opportunityMatrix.local.keywords, ['keyword', 'searchVolume', 'cpc', 'competition'], { 'competition': renderTag }));
    }
    if (keywordIdeasData.opportunityMatrix?.brandProtection?.keywords?.length > 0) {
        opportunityMatrixContent += createCard('Brand Protection Keywords', createTable(keywordIdeasData.opportunityMatrix.brandProtection.keywords, ['keyword', 'searchVolume', 'cpc', 'brandStrategy']));
    }
     if (opportunityMatrixContent) {
        content += createCard('Opportunity Matrix', opportunityMatrixContent, 'card-full-width');
    }

    if (keywordIdeasData.contentStrategy?.supportingContent) {
        let supportingContent = '';
        const sc = keywordIdeasData.contentStrategy.supportingContent;
        if(sc.howTo?.contentIdeas?.length > 0) supportingContent += createCard('"How To" Content Ideas', createTable(sc.howTo.contentIdeas, ['title', 'searchVolume', 'cpc', 'cta']));
        if(sc.comparison?.contentIdeas?.length > 0) supportingContent += createCard('Comparison Content Ideas', createTable(sc.comparison.contentIdeas, ['title', 'searchVolume', 'cpc', 'cta']));
        if(sc.problemSolving?.contentIdeas?.length > 0) supportingContent += createCard('Problem-Solving Content Ideas', createTable(sc.problemSolving.contentIdeas, ['title', 'searchVolume', 'cpc', 'cta']));
        if(supportingContent) content += createCard('Supporting Content Strategy', supportingContent, 'card-full-width');
    }

    if (keywordIdeasData.technicalSEO?.serpFeatures) {
        content += createCard('Top SERP Features', createKeyValueList(keywordIdeasData.technicalSEO.serpFeatures), 'card-full-width');
    }

    if (keywordIdeasData.actionPlan) {
        const { immediate, shortTerm, longTerm, budget } = keywordIdeasData.actionPlan;
        let actionContent = '';
        if(immediate?.length > 0) actionContent += '<h3>Immediate Actions (0-30 days)</h3><ul>' + immediate.map(i => `<li>${i}</li>`).join('') + '</ul>';
        if(shortTerm?.length > 0) actionContent += '<h3>Short-Term Plan (1-3 months)</h3><ul>' + shortTerm.map(i => `<li>${i}</li>`).join('') + '</ul>';
        if(longTerm?.length > 0) actionContent += '<h3>Long-Term Plan (6-12 months)</h3><ul>' + longTerm.map(i => `<li>${i}</li>`).join('') + '</ul>';
        if (budget?.totalRecommended) {
          actionContent += `<h3>Budget Recommendation</h3><p><strong>Total:</strong> ${budget.totalRecommended}</p>`;
        }
        content += createCard('Overall Action Plan', actionContent, 'card-full-width');
    }
    content += '</div>';
    return createSection('Keyword Ideas & Strategy', content);
}

function renderSearchIntent(intentData) {
    if (!intentData) return '';
    let content = '<div class="card-deck">';

    let topGrid = '<div class="two-col-grid">';
    if (intentData.all_keywords?.length > 0) {
        prepareSearchIntentChart(intentData.all_keywords);
        topGrid += createCard('Primary Intent Distribution', `<div class="chart-container" style="height: 300px;"><canvas id="searchIntentChart"></canvas></div>`);
    }
     if (intentData.strategic_recommendations?.high_priority_actions?.length > 0) {
        let recommendations = '<ul>' + intentData.strategic_recommendations.high_priority_actions.map(i => `<li>${i.replace(/\\"/g, '"')}</li>`).join('') + '</ul>';
        topGrid += createCard('High Priority Actions', recommendations);
    }
    topGrid += '</div>';
    content += topGrid;

    if (intentData.all_keywords?.length > 0) {
        content += createCard('Keyword Intent Breakdown', createTable(intentData.all_keywords, ['keyword', 'primary_intent', 'conversion_likelihood', 'recommended_action'], {
            'primary_intent': renderTag, 'conversion_likelihood': renderTag
        }), 'card-full-width');
    }
    content += '</div>';
    return createSection('Search Intent Analysis', content);
}

// --- MAIN TRANSFORMATION LOGIC ---

const data = $input.item.json;
if (!data) return [{ html: '<div class="error">No data provided.</div>' }];

const getNestedJson = (jsonString) => {
  try {
    const parsed = JSON.parse(jsonString);
    return Array.isArray(parsed) && parsed.length > 0 ? parsed[0]?.json : null;
  } catch (e) { return null; }
};

const googleSerpData = getNestedJson(data['Google SERP']);
const bingSerpData = getNestedJson(data['Bing SERP']);
const relatedKeywordsData = getNestedJson(data['Related Keywords']);
const keywordIdeasData = getNestedJson(data['Keyword IDeas']);
const searchIntentData = getNestedJson(data['Search Intent']);

let htmlContent = '';
const companyName = data['Company Name'] || 'Research Report';
const companyWebsite = data['Company Website'] || '';

htmlContent += createSection('Company & Target Overview', `<div class="key-value-pair"><div class="key">Company Website:</div><div class="value"><a href="${companyWebsite}" target="_blank">${companyWebsite}</a></div></div><div class="key-value-pair"><div class="key">Main Target Topic-Keyword:</div><div class="value">${data['Main Target Topic-Keyword']}</div></div>`);
htmlContent += renderSerpAnalysis(googleSerpData, 'Google SERP Analysis');
htmlContent += renderSerpAnalysis(bingSerpData, 'Bing SERP Analysis');
htmlContent += renderRelatedKeywords(relatedKeywordsData);
htmlContent += renderKeywordIdeas(keywordIdeasData);
htmlContent += renderSearchIntent(searchIntentData);

const finalChartScript = renderChartsScript();

// --- FINAL HTML OUTPUT ---
const htmlOutput = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${companyName} - Keyword Research Analysis</title>
  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
  <style>
    :root { 
        --color-primary: #ff6b35; 
        --color-secondary: #4a9eff; 
        --color-high: #c45850; 
        --color-medium: #e8c3b9; 
        --color-low: #3cba92;
        --color-opportunity-high: #2a9d8f;
        --color-opportunity-medium: #8ab17d;
        --color-opportunity-low: #e9c46a;
    }
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; background: #1a1a1a; color: #e0e0e0; line-height: 1.6; padding: 20px; }
    .container { max-width: 1200px; margin: 0 auto; background: #2d2d2d; border-radius: 12px; padding: 30px; }
    .header { text-align: center; margin-bottom: 40px; padding-bottom: 20px; border-bottom: 2px solid #444; }
    .header h1 { font-size: 2.5rem; color: var(--color-primary); font-weight: 300; }
    .section { margin-bottom: 25px; border: 1px solid #444; border-radius: 8px; overflow: hidden; background: #232323; }
    .section-header { background: #333; padding: 15px 20px; cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
    .section-header h2 { color: var(--color-primary); font-size: 1.3rem; font-weight: 500; }
    .section-content { padding: 20px; border-top: 1px solid #444; display: none; }
    .section.expanded .section-content { display: block; }
    .toggle-icon { font-size: 1.5rem; color: var(--color-primary); transition: transform 0.2s ease-in-out; }
    .section.expanded .toggle-icon { transform: rotate(45deg); }
    .card-deck { display: flex; flex-direction: column; gap: 20px; }
    .two-col-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(350px, 1fr)); gap: 20px; }
    .card { background: #2a2a2a; border: 1px solid #555; border-radius: 6px; }
    .card-header { padding: 12px 15px; border-bottom: 1px solid #555; }
    .card-header h3 { color: var(--color-primary); font-size: 1.1rem; }
    .card-content { padding: 15px; }
    .card-content h3 { font-size: 1.1em; color: #e0e0e0; margin-top: 10px; margin-bottom: 10px; padding-bottom: 5px; border-bottom: 1px solid #444;}
    .card-content ul { list-style-position: inside; padding-left: 5px; margin-bottom: 15px; }
    .card-content li { margin-bottom: 8px; }
    .table-container { overflow-x: auto; }
    table { width: 100%; border-collapse: collapse; }
    th, td { padding: 12px 15px; text-align: left; border-bottom: 1px solid #444; white-space: normal; }
    th { color: var(--color-primary); }
    .tag { padding: 4px 10px; border-radius: 12px; font-size: 0.85em; font-weight: 600; color: #fff; display: inline-block; }
    .tag-default { background-color: #555; }
    .tag-high { background-color: var(--color-high); }
    .tag-medium { background-color: var(--color-medium); color: #333; }
    .tag-low { background-color: var(--color-low); }
    .tag-opportunity-high { background-color: var(--color-opportunity-high); }
    .tag-opportunity-medium { background-color: var(--color-opportunity-medium); }
    .tag-opportunity-low { background-color: var(--color-opportunity-low); color: #333;}
    .chart-container { margin: 20px 0; }
    .key-value-pair { margin-bottom: 15px; padding: 10px; background: rgba(50, 50, 50, 0.5); border-radius: 4px; border-left: 3px solid var(--color-primary); }
    .key-value-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 15px; }
    .kv-item { padding: 10px; background: rgba(50, 50, 50, 0.5); border-radius: 4px; border-left: 3px solid var(--color-primary); }
    .kv-key, .key { font-weight: 600; color: var(--color-primary); margin-bottom: 5px; display: block; }
    .kv-value, .value { color: #ccc; }
    .kv-value small { display: block; color: #999; font-size: 0.9em; margin-top: 4px; }
    .value a { color: var(--color-secondary); }
  </style>
</head>
<body>
  <div class="container">
    <div class="header"><h1>${companyName} - Keyword Research Analysis</h1></div>
    ${htmlContent}
  </div>
  <script>
    function toggleSection(header) {
      const section = header.parentElement;
      section.classList.toggle('expanded');
      const icon = header.querySelector('.toggle-icon');
      icon.textContent = section.classList.contains('expanded') ? '−' : '+';
    }
    document.addEventListener('DOMContentLoaded', () => {
      const firstSectionHeader = document.querySelector('.section-header');
      if (firstSectionHeader) {
        toggleSection(firstSectionHeader);
      }
      ${finalChartScript}
    });
  </script>
</body>
</html>`;

return [{ html: htmlOutput }];

